let state={};const fmtBytes=n=>{const u=['B','KiB','MiB','GiB','TiB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',3000)}
async function api(path,options){const r=await fetch(path,options);const body=await r.json();if(!r.ok)throw new Error(body.error||r.statusText);return body}
async function refresh(){state=await api('/api/status');document.querySelector('#hostname').textContent=state.hostname;document.querySelector('#uptime').textContent=`up ${Math.floor(state.uptime_seconds/3600)} hours`;document.querySelector('#load').textContent=state.load.map(v=>v.toFixed(2)).join(' / ');document.querySelector('#disk').textContent=`${Math.round(state.disk.used/state.disk.total*100)}% used`;document.querySelector('#diskDetail').textContent=`${fmtBytes(state.disk.free)} free`;const available=Object.values(state.tools).filter(Boolean).length;document.querySelector('#toolCount').textContent=`${available} / ${Object.keys(state.tools).length}`;document.querySelector('#tools').innerHTML=Object.entries(state.tools).map(([k,v])=>`<span class="chip ${v?'ok':'warn'}">${esc(k)} · ${v?'ready':'missing'}</span>`).join('');if(state.tools.ntopng){document.querySelector('#tools').innerHTML+=` <a class="chip ok" href="http://${location.hostname}:3000/" target="_blank" rel="noopener">ntopng flows ↗</a>`}document.querySelector('#interfaces').innerHTML=`<table><thead><tr><th>Interface</th><th>State</th><th>Address</th><th>RX</th><th>Drops/errors</th><th>Type</th><th>Capture</th></tr></thead><tbody>${state.interfaces.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.state)}</td><td>${esc(i.addresses||'—')}</td><td>${fmtBytes(i.rx_bytes)}</td><td class="${i.rx_dropped+i.rx_errors?'bad':'ok'}">${i.rx_dropped+i.rx_errors}</td><td>${esc(i.kind||'')}${i.usb?' <span class="chip">USB</span>':''}</td><td class="${i.capture_allowed?'ok':'warn'}">${i.capture_allowed?'enabled':(i.capture_safe?'eligible':'off')}</td></tr>`).join('')}</tbody></table>`;document.querySelector('#targets').innerHTML=`<table><thead><tr><th>Name</th><th>Address</th><th>Profile</th><th>Port</th><th>Source</th><th>Actions</th></tr></thead><tbody>${state.targets.map(t=>`<tr><td>${esc(t.name)}</td><td>${ipLink(t.address)}</td><td>${esc(t.protocol)}</td><td>${t.port}</td><td>${esc(t.source||'file')}</td><td><button onclick="job('/api/check/${encodeURIComponent(t.name)}')">Check</button> <button onclick="job('/api/trace/${encodeURIComponent(t.name)}')">Trace route</button>${t.source==='dashboard'?` <button onclick="removeScope('${esc(t.address)}',${t.port})">Remove</button>`:''}</td></tr>`).join('')}</tbody></table>`;const ifaceOptions=state.interfaces.filter(i=>i.capture_allowed&&i.name!=='lo').map(i=>`<option>${esc(i.name)}</option>`).join('');document.querySelector('#captureIface').innerHTML=ifaceOptions||'<option value="">enable an interface in Settings</option>';document.querySelector('#healthIface').innerHTML=ifaceOptions||'<option value="">enable an interface in Settings</option>';const discoIfaces=state.interfaces.filter(i=>i.name!=='lo').sort((a,b)=>(b.addresses?1:0)-(a.addresses?1:0));const disco=document.querySelector('#discoIface');if(disco&&!disco.dataset.touched)disco.innerHTML=discoIfaces.map(i=>`<option>${esc(i.name)}</option>`).join('');await loadCaptures()}
// Poll /api/jobs until the given job finishes; resolve its parsed JSON output.
async function pollJob(jobId,tries=60){for(let i=0;i<tries;i++){await new Promise(r=>setTimeout(r,1200));const list=await api('/api/jobs');const j=list.find(x=>x.id===jobId);if(j&&j.state!=='running'){let out=j.output||'';try{return{job:j,data:JSON.parse(out)}}catch(e){return{job:j,data:{raw:out}}}}}throw new Error('job timed out')}
function startDiscovery(){const disco=document.querySelector('#discoIface');disco.dataset.touched='1';runJobInto('/api/discovery',{interface:disco.value,subnet:document.querySelector('#discoSubnet').value.trim()},'#discoStatus','#discoResult',renderDiscovery)}
function renderDiscovery(d){if(d.error||d.raw)return `<p class="hint bad">${esc(d.error||d.raw)}</p>`;const rows=(d.hosts||[]).map(h=>`<tr><td>${ipLink(h.ip)}</td><td>${esc(h.mac||'—')}</td><td>${esc(h.vendor||'')}</td><td>${esc(h.name||'')}</td><td>${esc(h.seen)}</td><td><button onclick="addScopeFromHost('${esc(h.ip)}','${esc(h.name||'')}')">Add to scope</button> <button onclick="snmpTo('${esc(h.ip)}')">SNMP</button></td></tr>`).join('');return `<p class="hint">${d.host_count} host(s) on ${esc(d.subnet)} via ${esc(d.interface)}</p><table><thead><tr><th>IP</th><th>MAC</th><th>Vendor</th><th>Name</th><th>Seen</th><th>Actions</th></tr></thead><tbody>${rows||'<tr><td colspan="6">no hosts responded</td></tr>'}</tbody></table>`}
// --- Click an IP to open its full dossier (Discovery / IDS / Endpoints / Neighbours) ---
function ipLink(ip){return ip?`<a href="#" class="iplink" onclick="showIp('${esc(ip)}');return false" title="Everything known about ${esc(ip)}">${esc(ip)}</a>`:'—'}
async function traceIp(ip){const box=document.querySelector('#ipTrace'),out=document.querySelector('#ipTraceOut');document.querySelector('#ipTraceTitle').textContent='Trace to '+ip;out.textContent='tracing…';box.style.display='block';try{const started=await api('/api/trace-ip',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip})});const{data,job}=await pollJob(started.job_id);out.textContent=(data&&data.raw!==undefined?data.raw:(job&&job.output))||'no output';loadJobs()}catch(e){out.textContent=e.message}}
// --- Approved-scope management ---
async function addScopeFromHost(ip,name){const port=window.prompt(`Add ${ip} to approved scope.\nTCP port to record (e.g. 502 Modbus, 102 S7, 4840 OPC UA, 22 SSH):`,'502');if(!port)return;const proto=window.prompt('Profile (tcp, s7-tcp, opcua-tcp):','tcp')||'tcp';try{const r=await api('/api/scope/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address:ip,name:name||('host-'+ip),port:+port,protocol:proto})});toast(r.status==='exists'?`${ip}:${port} already in scope`:`Added ${ip}:${port} to approved scope`);refresh()}catch(e){toast(e.message)}}
async function removeScope(address,port){if(!confirm(`Remove ${address}:${port} from approved scope?`))return;try{await api('/api/scope/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address,port})});toast('Removed');refresh()}catch(e){toast(e.message)}}
// --- IDS: fetch once, filter client-side ---
let idsData={alerts:[]};
async function loadIds(){const st=document.querySelector('#idsStatus');st.textContent='loading…';st.classList.remove('bad');document.querySelector('#idsSummary').innerHTML='';document.querySelector('#idsResult').innerHTML='';try{idsData=await api('/api/ids/alerts?limit=500');const e=idsData.engine||{};if(idsData.status!=='ok'){st.textContent=idsData.note||idsData.status;st.classList.add('bad')}else{const age=e.log_age_seconds!=null?`log updated ${e.log_age_seconds}s ago`:'';st.textContent=`Suricata ${e.service_active?'active':'installed (service not active)'} · ${age}`;st.classList.toggle('bad',!e.service_active)}document.querySelector('#idsSummary').innerHTML=Object.entries(idsData.by_severity||{}).map(([k,v])=>`<span class="chip ${sevClass(k)}">${esc(k)} · ${v}</span>`).join('')+(idsData.top_signatures||[]).slice(0,3).map(([s,n])=>`<span class="chip">${esc(s)} ×${n}</span>`).join('');renderIds()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderIds(){const sev=document.querySelector('#idsSev').value,q=document.querySelector('#idsQ').value.toLowerCase(),src=document.querySelector('#idsSrc').value,dst=document.querySelector('#idsDst').value;let list=idsData.alerts||[];list=list.filter(a=>(!sev||a.severity_label===sev)&&(!src||String(a.src||'').includes(src))&&(!dst||String(a.dst||'').includes(dst))&&(!q||((a.signature||'')+' '+(a.category||'')).toLowerCase().includes(q)));document.querySelector('#idsCount').textContent=`${list.length} shown`;const rows=list.map(a=>`<tr><td>${esc(a.time)}</td><td class="${sevClass(a.severity_label)}">${esc(a.severity_label)}</td><td>${esc(a.signature)}</td><td>${esc(a.category||'')}</td><td>${ipLink(a.src)}${a.sport?':'+a.sport:''}</td><td>${ipLink(a.dst)}${a.dport?':'+a.dport:''}</td><td>${esc(a.proto||'')}${a.app_proto&&a.app_proto!=='failed'?' · '+esc(a.app_proto):''}</td><td>${a.flow_id?`<button onclick="showAlert('${esc(a.flow_id)}')">Details</button>`:'—'}</td></tr>`).join('');document.querySelector('#idsResult').innerHTML=`<table><thead><tr><th>Time</th><th>Severity</th><th>Signature</th><th>Category</th><th>Source</th><th>Destination</th><th>Proto</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="8">${(idsData.status==='ok')?'No alerts match.':esc(idsData.note||'')}</td></tr>`}</tbody></table>`}
// --- IDS capture adapter (auto/all/specific) ---
let idsAdapter={};
async function loadIdsAdapter(){try{idsAdapter=await api('/api/ids/adapter')}catch(e){document.querySelector('#idsAdapterLive').innerHTML=`<span class="bad">${esc(e.message)}</span>`;return}renderIdsAdapter()}
function renderIdsAdapter(){const d=idsAdapter,cfg=d.live||{};document.querySelectorAll('input[name="idsMode"]').forEach(r=>{r.checked=(r.value===d.mode)});document.querySelector('#idsRecheck').value=d.recheck_seconds||60;const active=(cfg.active_interfaces||[]).join(', ')||'unknown';const note=cfg.note?` — ${esc(cfg.note)}`:'';document.querySelector('#idsAdapterLive').innerHTML=`Suricata ${d.service_active?'<span class="ok">active</span>':'<span class="bad">not active</span>'} · capturing on <strong>${esc(active)}</strong>${note}`;const chosen=new Set(d.mode==='manual'?(d.interfaces||[]):[]);const rows=(d.adapters||[]).map(a=>`<tr><td><label class="inline"><input type="checkbox" class="idsNic" value="${esc(a.name)}" ${chosen.has(a.name)?'checked':''} ${d.mode==='manual'?'':'disabled'}> ${esc(a.name)}</label></td><td>${a.wired?'wired':'wireless'}</td><td class="${a.up?'ok':'warn'}">${a.up?'up':'down (prepared)'}</td><td>${(cfg.active_interfaces||[]).includes(a.name)?'★ capturing':''}</td></tr>`).join('');document.querySelector('#idsAdapterNics').innerHTML=`<table><thead><tr><th>Watch</th><th>Type</th><th>Link</th><th>Live</th></tr></thead><tbody>${rows||'<tr><td colspan="4">no NICs found</td></tr>'}</tbody></table>`}
function idsModeChange(){const mode=document.querySelector('input[name="idsMode"]:checked').value;document.querySelectorAll('.idsNic').forEach(c=>c.disabled=(mode!=='manual'))}
async function saveIdsAdapter(){const mode=(document.querySelector('input[name="idsMode"]:checked')||{}).value||'auto';const interfaces=[...document.querySelectorAll('.idsNic:checked')].map(c=>c.value);const recheck_seconds=+document.querySelector('#idsRecheck').value||60;if(mode==='manual'&&!interfaces.length){toast('Pick at least one NIC for Specific mode');return}try{idsAdapter=await api('/api/ids/adapter',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,interfaces,recheck_seconds})});toast('IDS adapter saved — the daemon applies it within one recheck');renderIdsAdapter();setTimeout(loadIdsAdapter,3000)}catch(e){toast(e.message)}}
// --- Neighbours: LLDP + SNMP ---
async function loadLldp(){const st=document.querySelector('#lldpStatus');st.textContent='loading…';st.classList.remove('bad');try{const d=await api('/api/lldp');if(d.status!=='ok'){st.textContent=d.note||d.status;st.classList.add('bad');document.querySelector('#lldpResult').innerHTML='';return}st.textContent=`${d.neighbors.length} neighbour(s)`;document.querySelector('#lldpResult').innerHTML=`<table><thead><tr><th>Local port</th><th>System</th><th>Remote port</th><th>Mgmt IP</th><th>VLAN</th><th>Description</th></tr></thead><tbody>${d.neighbors.map(n=>`<tr><td>${esc(n.local_port)}</td><td>${esc(n.system)}</td><td>${esc(n.port_id)}${n.port_descr?' ('+esc(n.port_descr)+')':''}</td><td>${ipLink(n.mgmt_ip)}</td><td>${esc(n.vlan||'')}</td><td>${esc(n.descr||'')}</td></tr>`).join('')||'<tr><td colspan="6">no neighbours yet</td></tr>'}</tbody></table>`}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function snmpTo(ip){document.querySelectorAll('nav button,.view').forEach(e=>e.classList.remove('active'));document.querySelector('nav button[data-view="neighbours"]').classList.add('active');document.querySelector('#neighbours').classList.add('active');document.querySelector('#snmpIp').value=ip;runSnmp()}
async function runSnmp(){const ip=document.querySelector('#snmpIp').value.trim(),st=document.querySelector('#snmpStatus');if(!ip){st.textContent='enter an IP';st.classList.add('bad');return}st.textContent='querying…';st.classList.remove('bad');document.querySelector('#snmpResult').innerHTML='';try{const started=await api('/api/snmp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip,walk_interfaces:document.querySelector('#snmpIfaces').checked})});const{data}=await pollJob(started.job_id);st.textContent='';if(data.status!=='ok'){st.textContent=data.note||data.status;st.classList.add('bad');return}const sys=data.system||{};const rows=Object.entries(sys).filter(([,v])=>v).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('');const ifaces=(data.interfaces||[]).length?`<p class="hint">Interfaces: ${data.interfaces.map(esc).join(', ')}</p>`:'';document.querySelector('#snmpResult').innerHTML=`<table><thead><tr><th>OID</th><th>Value</th></tr></thead><tbody>${rows||'<tr><td colspan="2">no values</td></tr>'}</tbody></table>${ifaces}`}catch(e){st.textContent=e.message;st.classList.add('bad')}}
// --- Settings ---
function snmpVerToggle(){const v=document.querySelector('#snmpVer').value;document.querySelector('#snmpV2').style.display=v==='2c'?'':'none';document.querySelector('#snmpV3').style.display=v==='3'?'':'none'}
async function loadSettings(){const s=await api('/api/settings');const snmp=s.snmp||{};document.querySelector('#snmpVer').value=snmp.version||'2c';snmpVerToggle();document.querySelector('#snmpCommunitySet').textContent=snmp.community_set?'· stored':'· not set';const v3=snmp.v3||{};document.querySelector('#v3User').value=v3.user||'';document.querySelector('#v3Level').value=v3.level||'authPriv';document.querySelector('#v3AuthProto').value=v3.auth_proto||'SHA';document.querySelector('#v3PrivProto').value=v3.priv_proto||'AES';document.querySelector('#v3AuthKeySet').textContent=v3.auth_key_set?'· stored':'· not set';document.querySelector('#v3PrivKeySet').textContent=v3.priv_key_set?'· stored':'· not set';renderIfaceSettings()}
function renderIfaceSettings(){const rows=(state.interfaces||[]).filter(i=>i.name!=='lo').map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.kind||'')}${i.usb?' <span class="chip">USB</span>':''}</td><td>${esc(i.addresses||'—')}</td><td><label class="inline"><input type="checkbox" ${i.capture_allowed?'checked':''} onchange="setCapture('${esc(i.name)}',this.checked)"> capture enabled</label>${i.capture_safe?'':' <span class="chip warn">has IP</span>'}</td></tr>`).join('');document.querySelector('#ifaceSettings').innerHTML=`<table><thead><tr><th>Interface</th><th>Type</th><th>Address</th><th>Capture / monitor</th></tr></thead><tbody>${rows}</tbody></table>`}
async function setCapture(name,allowed){try{await api(`/api/interfaces/${encodeURIComponent(name)}/capture`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({capture_allowed:allowed})});toast(`${name}: capture ${allowed?'enabled':'disabled'}`);await refresh();renderIfaceSettings()}catch(e){toast(e.message)}}
async function saveSnmp(){const v=document.querySelector('#snmpVer').value;const snmp={version:v,v3:{user:document.querySelector('#v3User').value,level:document.querySelector('#v3Level').value,auth_proto:document.querySelector('#v3AuthProto').value,priv_proto:document.querySelector('#v3PrivProto').value,auth_key:document.querySelector('#v3AuthKey').value,priv_key:document.querySelector('#v3PrivKey').value}};const c=document.querySelector('#snmpCommunity').value;if(c)snmp.community=c;const st=document.querySelector('#snmpSaveStatus');try{await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({snmp})});st.textContent='saved';st.classList.remove('bad');document.querySelector('#snmpCommunity').value='';document.querySelector('#v3AuthKey').value='';document.querySelector('#v3PrivKey').value='';loadSettings()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
// --- Settings: sustained-state alerting (#53) -------------------------------
const ALERT_STATE={insufficient_data:'ok',stable:'ok',spike:'warn',rising:'warn',degraded:'bad'};
function alertBadge(st){return `<span class="chip ${ALERT_STATE[st]||''}">${esc(st||'?')}</span>`}
async function loadAlerting(){let d;try{d=await api('/api/alerts')}catch(e){const el=document.querySelector('#alSignals');if(el){el.innerHTML=`<span class="bad">${esc(e.message)}</span>`}return}const a=d.config||{};document.querySelector('#alEnabled').checked=!!a.enabled;document.querySelector('#alMinState').value=a.min_state||'rising';document.querySelector('#alPoll').value=a.poll_seconds||60;document.querySelector('#alWindow').value=a.window_minutes||60;const sig=a.signals||{};document.querySelector('#alSigTcp').checked=sig.tcp_retransmit!==false;document.querySelector('#alSigDns').checked=sig.dns_failure!==false;document.querySelector('#alSigOutage').checked=sig.outage!==false;const wh=a.webhook||{};document.querySelector('#alWhEnabled').checked=!!wh.enabled;document.querySelector('#alWhUrl').value=wh.url||'';const em=a.email||{};document.querySelector('#alEmEnabled').checked=!!em.enabled;document.querySelector('#alEmTls').checked=em.use_tls!==false;document.querySelector('#alEmHost').value=em.smtp_host||'';document.querySelector('#alEmPort').value=em.smtp_port||587;document.querySelector('#alEmUser').value=em.username||'';document.querySelector('#alEmFrom').value=em.from_addr||'';document.querySelector('#alEmTo').value=em.to_addrs||'';document.querySelector('#alEmPass').value='';document.querySelector('#alEmPassSet').textContent=em.password_set?'· stored':'· not set';
  const live=d.signals||[];document.querySelector('#alSignals').innerHTML=live.length?live.map(s=>`${alertBadge(s.state)} <strong>${esc(s.title)}</strong> ${esc(s.value)} <span class="hint">${esc(s.summary||'')}</span>`).join('<br>'):(a.enabled?'<span class="hint">no signal data yet</span>':'<span class="hint">alerting disabled</span>');
  const hist=d.history||[];document.querySelector('#alHistory').innerHTML=hist.length?`<table><thead><tr><th>When</th><th>Signal</th><th>Transition</th><th>State</th><th>Delivery</th></tr></thead><tbody>${hist.map(h=>{const dv=Object.entries(h.delivery||{}).map(([c,r])=>`${esc(c)}:${r&&r.ok?'ok':'fail'}`).join(' ')||'—';return `<tr><td>${h.ts?new Date(h.ts*1000).toLocaleString():'—'}</td><td>${esc(h.title||h.id)}</td><td class="${h.kind==='resolved'?'ok':'bad'}">${esc(h.kind)}</td><td>${alertBadge(h.state)}</td><td>${esc(dv)}</td></tr>`}).join('')}</tbody></table>`:'<p class="hint">No alerts fired yet.</p>'}
async function saveAlerting(){const email={enabled:document.querySelector('#alEmEnabled').checked,use_tls:document.querySelector('#alEmTls').checked,smtp_host:document.querySelector('#alEmHost').value.trim(),smtp_port:+document.querySelector('#alEmPort').value||587,username:document.querySelector('#alEmUser').value.trim(),from_addr:document.querySelector('#alEmFrom').value.trim(),to_addrs:document.querySelector('#alEmTo').value.trim()};const pw=document.querySelector('#alEmPass').value;if(pw)email.password=pw;const alerting={enabled:document.querySelector('#alEnabled').checked,min_state:document.querySelector('#alMinState').value,poll_seconds:+document.querySelector('#alPoll').value||60,window_minutes:+document.querySelector('#alWindow').value||60,signals:{tcp_retransmit:document.querySelector('#alSigTcp').checked,dns_failure:document.querySelector('#alSigDns').checked,outage:document.querySelector('#alSigOutage').checked},webhook:{enabled:document.querySelector('#alWhEnabled').checked,url:document.querySelector('#alWhUrl').value.trim()},email};const st=document.querySelector('#alSaveStatus');try{await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({alerting})});st.textContent='saved';st.classList.remove('bad');document.querySelector('#alEmPass').value='';loadAlerting()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function testAlert(){const st=document.querySelector('#alSaveStatus');st.textContent='sending test…';st.classList.remove('bad');try{const r=await api('/api/alerts/test',{method:'POST'});const parts=Object.entries(r.delivery||{}).map(([c,x])=>`${c}: ${x&&x.ok?'ok':('fail'+(x&&x.error?' ('+x.error+')':''))}`);st.textContent=parts.length?('test → '+parts.join(', ')):'test sent';st.classList.toggle('bad',parts.some(p=>p.includes('fail')))}catch(e){st.textContent=e.message;st.classList.add('bad')}}
// --- Settings: session / acceptance report export (task #48) ----------------
// Same-origin GET carries the session cookie, so a plain navigation authenticates.
// HTML opens in a new tab for review; JSON/CSV download as attachments.
function downloadReport(fmt){const m=(document.querySelector('#rpWindow')||{}).value||'1440';const url=`/api/report/session?format=${fmt}&minutes=${m}`;if(fmt==='html'){window.open(url,'_blank');return}const a=document.createElement('a');a.href=url;a.rel='noopener';document.body.appendChild(a);a.click();a.remove()}
// --- Freeze-evidence bundles (task #47) ---
function evBytes(n){if(n==null)return'—';const u=['B','KB','MB','GB','TB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return`${v.toFixed(i?1:0)} ${u[i]}`}
async function freezeEvidence(){const s=document.querySelector('#evStatus');if(s)s.textContent='freezing…';try{const r=await api('/api/evidence/freeze',{method:'POST'});if(s)s.textContent=`froze ${r.bundle_id} (${evBytes(r.bytes)}, verdict: ${r.verdict||'—'})${r.rotated&&r.rotated.length?`, rotated ${r.rotated.length} old`:''}`;toast('evidence bundle frozen');loadEvidence()}catch(e){if(s)s.textContent='refused: '+e.message;toast(e.message)}}
async function loadEvidence(){const el=document.querySelector('#evList');if(!el)return;try{const d=await api('/api/evidence');const meta=`<p class="hint">Store: <code>${esc(d.dir)}</code> · free ${evBytes(d.free_bytes)} · reserve ${evBytes(d.reserve_bytes)} · keep newest ${d.max_bundles}.</p>`;if(!d.bundles.length){el.innerHTML=meta+'<p class="hint">No bundles yet.</p>';return}const rows=d.bundles.map(b=>{const dl=(b.files||[]).map(f=>`<a href="/api/evidence/${encodeURIComponent(b.id)}/${encodeURIComponent(f)}" rel="noopener">${esc(f)}</a>`).join(' · ');const when=b.created?new Date(b.created*1000).toLocaleString():'—';const dig=b.bundle_digest?esc(b.bundle_digest.slice(0,12)):'—';return `<tr><td>${esc(b.id)}</td><td>${when}</td><td>${evBytes(b.bytes)}</td><td><code>${dig}…</code></td><td>${dl}</td></tr>`}).join('');el.innerHTML=meta+`<table><thead><tr><th>Bundle</th><th>Created</th><th>Size</th><th>Digest</th><th>Files</th></tr></thead><tbody>${rows}</tbody></table>`}catch(e){el.innerHTML='<p class="hint">'+esc(e.message)+'</p>'}}
// --- Settings: saveable named custom services -------------------------------
async function loadCustomServices(){let d;try{d=await api('/api/services/catalog')}catch(e){return}const list=d.custom||[];document.querySelector('#customSvcList').innerHTML=list.length?`<table><thead><tr><th>Name</th><th>Port</th><th>Proto</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.port}</td><td>${esc(s.proto)}</td><td><button onclick="removeCustomService('${esc(s.name)}')">Remove</button></td></tr>`).join('')}</tbody></table>`:'<p class="hint">No custom services yet. Add one above and it appears in the Actions service picker under “Custom”.</p>'}
async function addCustomService(){const name=document.querySelector('#csName').value.trim(),port=document.querySelector('#csPort').value.trim(),proto=document.querySelector('#csProto').value;if(!name||!port){toast('enter a name and port');return}try{const r=await api('/api/services/custom/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,port:+port,proto})});toast(r.status==='exists'?`'${name}' already saved`:`Saved ${name} · ${port}/${proto}`);document.querySelector('#csName').value='';document.querySelector('#csPort').value='';loadCustomServices();loadCatalog(true)}catch(e){toast(e.message)}}
async function removeCustomService(name){if(!confirm('Remove custom service '+name+'?'))return;try{await api('/api/services/custom/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});toast('removed '+name);loadCustomServices();loadCatalog(true)}catch(e){toast(e.message)}}
function startSurvey(){runJobInto('/api/wifi/survey',{interface:'',rescan:true},'#surveyStatus','#surveyResult',renderSurvey,'#surveyChannels')}
function renderSurvey(d){renderWifiAssess(d&&d.assessment);if(d.error||d.raw)return `<p class="hint bad">${esc(d.error||d.raw)}</p>`;if(d.note&&!(d.aps||[]).length)return `<p class="hint bad">${esc(d.note)}</p>`;const rows=(d.aps||[]).map(a=>{const sig=a.signal_dbm!=null?`${a.signal_dbm} dBm`:(a.signal_pct!=null?`${a.signal_pct}%`:'—');return `<tr><td>${a.in_use?'★ ':''}${esc(a.ssid)}</td><td>${esc(a.bssid)}</td><td>${esc(a.band)}</td><td>${a.channel||'—'}</td><td>${sig}</td><td>${esc(a.security)}</td></tr>`}).join('');return `<p class="hint">${d.ap_count} AP(s) on ${esc(d.interface)} (via ${esc(d.backend)})</p><table><thead><tr><th>SSID</th><th>BSSID</th><th>Band</th><th>Ch</th><th>Signal</th><th>Security</th></tr></thead><tbody>${rows||'<tr><td colspan="6">no APs found</td></tr>'}</tbody></table>`}
function renderWifiAssess(a){const el=document.querySelector('#wifiAssess');if(!el)return;if(!a||!Object.keys(a).length)return;const cov=a.coverage||{};const s=a.strongest;const bands=(a.bands||[]).map(b=>`${esc(b.band)} ×${b.ap_count}`).join(', ')||'—';const sec=(a.security||[]).map(x=>`${esc(x.type)} ×${x.ap_count}`).join(', ')||'—';const cards=[`<div><strong>Coverage</strong><span>${cov.strong||0} strong · ${cov.fair||0} fair · ${cov.weak||0} weak${s?`<br>best: ${esc(s.ssid)} @ ${s.approx_dbm} dBm (${esc(s.band)} ch${s.channel})`:''}</span></div>`,`<div><strong>Bands / RF design</strong><span>${bands}${(a.co_channel||[]).length?`<br>co-channel: ${a.co_channel.map(c=>`${esc(c.band)} ch${c.channel} ×${c.ap_count}`).join(', ')}`:'<br>no channel congestion'}</span></div>`,`<div><strong>Security</strong><span>${sec}${a.open_count?`<br><span class="bad">${a.open_count} open network(s)</span>`:''}</span></div>`,`<div><strong>Rogue / evil-twin clues</strong><span>${(a.same_ssid_multi_bssid||[]).length?a.same_ssid_multi_bssid.map(t=>`${esc(t.ssid)} on ${t.bssid_count} BSSIDs`).join('; '):'no SSID on multiple BSSIDs'}${a.hidden_count?`<br>${a.hidden_count} hidden SSID(s)`:''}</span></div>`];const notes=(a.notes||[]).map(n=>`<li>${esc(n)}</li>`).join('');el.innerHTML=`<div class="check-grid">${cards.join('')}</div>${notes?`<ul class="hint" style="margin-top:.6rem">${notes}</ul>`:''}`}
function renderChannels(d,sel){if(!sel)return;const el=document.querySelector(sel);if(!el)return;el.innerHTML=(d.channels||[]).map(c=>`<span class="chip">${esc(c.band)} ch${c.channel} · ${c.ap_count} AP${c.ap_count>1?'s':''}</span>`).join('')}
async function runJobInto(url,payload,statusSel,resultSel,render,channelsSel){const status=document.querySelector(statusSel),result=document.querySelector(resultSel);status.textContent='running…';status.classList.remove('bad');result.innerHTML='';if(channelsSel)document.querySelector(channelsSel).innerHTML='';try{const started=await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const{data}=await pollJob(started.job_id);status.textContent='';if(channelsSel)renderChannels(data,channelsSel);result.innerHTML=render(data);loadJobs()}catch(e){status.textContent=e.message;status.classList.add('bad')}}
async function job(url,payload){try{const result=await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined});toast(`Job ${result.job_id} started`);loadJobs()}catch(e){toast(e.message)}}
// --- Health profiles (Health tab) ---
function hpTargets(){return{host:document.querySelector('#hpTarget').value.trim(),port:document.querySelector('#hpPort').value.trim()}}
function hpRun(kind){const{host,port}=hpTargets();if(!host){toast('enter a host or IP');return}
  if(kind==='path')return runJobInto('/api/actions/path-health',{host,port:port?+port:0},'#hpStatus','#hpResult',renderPathHealth);
  if(kind==='services')return runJobInto('/api/actions/service-health',{host,port:port?+port:443},'#hpStatus','#hpResult',renderServiceHealth);
  if(kind==='infra')return runJobInto('/api/snmp',{ip:host,walk_interfaces:true},'#hpStatus','#hpResult',renderSnmp);
  if(kind==='baseline')return hpBaseline(host);}
function renderSnmp(d){if(!d||d.status!=='ok')return `<p class="hint bad">${esc((d&&(d.note||d.status))||'no result')}</p>`;const sys=d.system||{};const rows=Object.entries(sys).filter(([,v])=>v).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('');const ifs=(d.interfaces||[]).length?`<p class="hint">Interfaces: ${d.interfaces.map(esc).join(', ')}</p>`:'';return `<table><thead><tr><th>OID</th><th>Value</th></tr></thead><tbody>${rows||'<tr><td colspan="2">no values</td></tr>'}</tbody></table>${ifs}`}
function renderPathHealth(d){if(!d||d.raw)return `<pre>${esc((d&&d.raw)||'no output')}</pre>`;const r=d.route||{},l=d.latency||{};let out='<table><tbody>';out+=`<tr><td>Loss</td><td>${l.loss_pct!=null?l.loss_pct+'%':'—'}${l.received!=null?` (${l.received}/${l.sent})`:''}</td></tr>`;out+=`<tr><td>RTT min/avg/max</td><td>${l.rtt_avg_ms!=null?`${l.rtt_min_ms} / ${l.rtt_avg_ms} / ${l.rtt_max_ms} ms`:'—'}</td></tr>`;out+=`<tr><td>Jitter</td><td>${l.jitter_ms!=null?l.jitter_ms+' ms':'—'}</td></tr>`;out+=`<tr><td>Path MTU</td><td>${r.pmtu!=null?r.pmtu+' bytes':'—'}</td></tr>`;out+=`<tr><td>Hops</td><td>${r.hop_count!=null?r.hop_count:'—'}${r.reached?' · reached':''}</td></tr>`;if(d.tcp)out+=`<tr><td>TCP :${d.tcp.port}</td><td>${d.tcp.open?`open · ${d.tcp.connect_ms} ms`:esc(d.tcp.error||'closed')}</td></tr>`;out+='</tbody></table>';const hops=(r.hops||[]).map(h=>`<tr><td>${h.hop}</td><td>${esc(h.address)}</td><td>${h.rtt_ms!=null?h.rtt_ms+' ms':'—'}</td></tr>`).join('');if(hops)out+=`<table style="margin-top:.6rem"><thead><tr><th>#</th><th>Hop</th><th>RTT</th></tr></thead><tbody>${hops}</tbody></table>`;if(!l.ok&&l.error)out=`<p class="hint">${esc(l.error)}</p>`+out;return out}
async function hpBaseline(target){const st=document.querySelector('#hpStatus'),res=document.querySelector('#hpResult');st.textContent='reading baseline…';st.classList.remove('bad');res.innerHTML='';try{const d=await api('/api/health/baseline?target='+encodeURIComponent(target));st.textContent='';res.innerHTML=renderBaseline(d)}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderBaseline(d){if(d.error)return `<p class="hint bad">${esc(d.error)}</p>`;if(d.note)return `<p class="hint">${esc(d.note)}. Baselines only cover targets the outage monitor pings — check the Monitor tab for those.</p>`;const b=d.baseline||{},c=d.current_hour||{};const v=d.verdict==='ok'?'<span class="chip ok">within baseline</span>':'<span class="chip bad">elevated</span>';const notes=(d.notes||[]).map(n=>`<li>${esc(n)}</li>`).join('');return `<p>${v} · ${d.window_days}-day baseline vs last hour</p><table><thead><tr><th>Metric</th><th>7-day</th><th>Last hour</th></tr></thead><tbody><tr><td>Samples</td><td>${b.samples}</td><td>${c.samples}</td></tr><tr><td>Loss</td><td>${b.loss_pct!=null?b.loss_pct+'%':'—'}</td><td>${c.loss_pct!=null?c.loss_pct+'%':'—'}</td></tr><tr><td>RTT median</td><td>${b.rtt_median_ms!=null?b.rtt_median_ms+' ms':'—'}</td><td>${c.rtt_median_ms!=null?c.rtt_median_ms+' ms':'—'}</td></tr><tr><td>RTT p95</td><td>${b.rtt_p95_ms!=null?b.rtt_p95_ms+' ms':'—'}</td><td>${c.rtt_p95_ms!=null?c.rtt_p95_ms+' ms':'—'}</td></tr></tbody></table>${notes?`<ul class="hint">${notes}</ul>`:''}`}
function startCapture(){job('/api/capture',{interface:document.querySelector('#captureIface').value,seconds:+document.querySelector('#captureSeconds').value,files:+document.querySelector('#captureFiles').value,size_mib:+document.querySelector('#captureSize').value})}
function startL2Health(){job('/api/l2-health',{interface:document.querySelector('#healthIface').value,duration:+document.querySelector('#healthDuration').value})}
async function loadCaptures(){const files=await api('/api/captures');document.querySelector('#capturesList').innerHTML=`<table><thead><tr><th>File</th><th>Size</th><th>Modified</th><th>Actions</th></tr></thead><tbody>${files.map(f=>`<tr><td>${esc(f.name)}</td><td>${fmtBytes(f.size)}</td><td>${new Date(f.modified*1000).toLocaleString()}</td><td><button onclick="job('/api/summarize/${encodeURIComponent(f.name)}')">Analyze</button> <a href="/api/download/${encodeURIComponent(f.name)}"><button>Download</button></a></td></tr>`).join('')}</tbody></table>`}
async function loadJobs(){const list=await api('/api/jobs');document.querySelector('#jobsList').innerHTML=list.reverse().map(j=>{const running=j.state==='running'||j.state==='stopping';const stop=running?` <button onclick="stopJob('${esc(j.id)}')">Stop</button>`:'';const view=(!running&&j.output)?` <button onclick="viewJob('${esc(j.id)}')">View result</button>`:'';return `<div class="job"><strong class="${j.state==='failed'?'bad':(running?'warn':'ok')}">${esc(j.kind)} · ${esc(j.state)}</strong>${j.target?`<span class="clock"> ${esc(j.target)}</span>`:''}<span class="clock"> ${esc(j.id)}</span>${view}${stop}${j.output?`<pre>${esc(j.output)}</pre>`:''}</div>`}).join('')||'<p class="hint">No jobs yet.</p>'}
// Re-open any finished job's result later, rendered by kind (the "look up
// results after leaving the page" viewer). Reuses the detail modal.
async function viewJob(id){let j;try{j=await api('/api/jobs/'+encodeURIComponent(id))}catch(e){toast(e.message);return}
  document.querySelector('#alertDetailTitle').textContent=(j.kind||'job')+' · '+id;
  let data=null;try{data=JSON.parse(j.output||'')}catch(e){}
  const meta=`<div class="chips"><span class="chip ${j.state==='failed'?'bad':(j.state==='complete'?'ok':'warn')}">${esc(j.state)}</span>${j.target?`<span class="chip">${esc(j.target)}</span>`:''}<span class="chip">started ${fmtTs(j.started)}</span>${j.ended?`<span class="chip">ended ${fmtTs(j.ended)}</span>`:''}${j.code!=null?`<span class="chip">exit ${esc(j.code)}</span>`:''}</div>`;
  document.querySelector('#alertDetailBody').innerHTML=meta+renderJobResult(j.kind,data,j.output);
  document.querySelector('#alertDetail').style.display='flex'}
function renderJobResult(kind,data,raw){
  if(data&&!data.raw){if(kind==='lan-discovery'&&data.hosts)return renderDiscovery(data);if(kind==='wifi-survey'&&(data.aps||data.note))return renderSurvey(data);if(kind==='service-health'&&(data.dns||data.tcp))return renderServiceHealth(data);if(kind==='path-health'&&(data.route||data.latency))return renderPathHealth(data);if(kind==='snmp-probe'&&data.status){if(data.status!=='ok')return `<p class="hint bad">${esc(data.note||data.status)}</p>`;const sys=data.system||{};const rows=Object.entries(sys).filter(([,v])=>v).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('');const ifs=(data.interfaces||[]).length?`<p class="hint">Interfaces: ${data.interfaces.map(esc).join(', ')}</p>`:'';return `<table><thead><tr><th>OID</th><th>Value</th></tr></thead><tbody>${rows||'<tr><td colspan="2">no values</td></tr>'}</tbody></table>${ifs}`}}
  return `<pre>${esc((raw&&raw.length)?raw:'(no output captured)')}</pre>`}
async function stopJob(id){if(!confirm('Stop this job? A ring capture keeps the files already written to disk.'))return;try{const r=await api('/api/jobs/'+encodeURIComponent(id)+'/stop',{method:'POST'});toast('Stopping '+id);setTimeout(loadJobs,1500)}catch(e){toast(e.message)}}
async function loadWifi(){const data=await api('/api/wifi');document.querySelector('#wifiData').textContent=data.length?data.map(d=>`[${d.interface}]\n${d.info}\n${d.link}`).join('\n'): 'No Linux wireless interface was detected.'}
// --- Wi-Fi AP proximity map (radial: radius ~ inverse signal) ---
function sigQuality(text){if(!text)return null;const m=String(text).match(/(-?\d+(?:\.\d+)?)/);if(!m)return null;const n=+m[1];if(/dbm/i.test(text)||n<0)return Math.max(0,Math.min(1,(n+90)/60));return Math.max(0,Math.min(1,n/100))}// dBm -90..-30 or 0..100%
function bandColor(band){band=String(band||'');if(band.indexOf('2.4')>=0)return 'var(--amber)';if(band.indexOf('6')>=0)return 'var(--blue)';return 'var(--cyan)'}
async function loadWifiMap(){const st=document.querySelector('#wifiMapStatus');st.textContent='loading…';st.classList.remove('bad');try{const [ap,ho]=await Promise.all([api('/api/wifi/ap-monitor'),api('/api/wifi/handovers?minutes=60&limit=1').catch(()=>({current:{}}))]);const cur=Object.values(ho.current||{}).find(c=>c&&c.connected)||{};renderWifiMap((ap.access_points||[]).filter(a=>a.present),cur);st.textContent=`${(ap.access_points||[]).filter(a=>a.present).length} AP(s) on air · updated ${fmtTs(ap.last_update)}`}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderWifiMap(aps,cur){const mapEl=document.querySelector('#wifiMap'),legEl=document.querySelector('#wifiMapLegend');if(!mapEl)return;if(!aps.length){mapEl.innerHTML='<p class="hint">No access points on air. Scan on the Access Points tab (the radio must be enabled).</p>';legEl.innerHTML='';return}
  const curB=(cur.bssid||'').toLowerCase();const pts=aps.map(a=>({...a,q:sigQuality(a.signal),self:(a.bssid||'').toLowerCase()===curB})).sort((x,y)=>(y.q||0)-(x.q||0));
  const C=200,inner=34,outer=176;const ring=(r,lbl)=>`<circle cx="${C}" cy="${C}" r="${r}" fill="none" stroke="var(--line)" stroke-dasharray="3 4"/><text x="${C}" y="${C-r-3}" text-anchor="middle" font-size="9">${lbl}</text>`;
  let marks='';pts.forEach((p,i)=>{const q=p.q==null?0.25:p.q;const r=inner+(1-q)*(outer-inner);const ang=(-90+i*(360/pts.length))*Math.PI/180;const x=C+r*Math.cos(ang),y=C+r*Math.sin(ang);const col=bandColor(p.band);const rad=p.self?7:5;marks+=`<line x1="${C}" y1="${C}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}" stroke="${p.self?'var(--cyan)':'var(--line)'}" stroke-width="${p.self?1.5:0.6}" opacity="0.6"/>`;marks+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${rad}" fill="${col}" stroke="${p.self?'var(--text)':'#0a0f14'}" stroke-width="${p.self?2:1}"><title>${esc(p.ssid||'(hidden)')} · ${esc(p.band||'')} ch${p.channel||'?'} · ${esc(p.signal||'')}${p.self?' · associated':''}</title></circle>`;if(p.self)marks+=`<text x="${x.toFixed(1)}" y="${(y-10).toFixed(1)}" text-anchor="middle" font-size="9" fill="var(--cyan)">★</text>`});
  mapEl.innerHTML=`<svg viewBox="0 0 400 400" xmlns="http://www.w3.org/2000/svg">${ring(outer,'weak')}${ring(105,'fair')}${ring(inner+6,'strong')}${marks}<circle cx="${C}" cy="${C}" r="6" fill="var(--text)"/><text x="${C}" y="${C+20}" text-anchor="middle" font-size="10" fill="var(--text)">this probe</text></svg>`;
  legEl.innerHTML=`<table><thead><tr><th></th><th>SSID</th><th>Band</th><th>Ch</th><th>Signal</th></tr></thead><tbody>${pts.map(p=>`<tr><td><span class="dot" style="background:${bandColor(p.band)}"></span></td><td>${p.self?'★ ':''}${esc(p.ssid||'(hidden)')}</td><td>${esc(p.band||'')}</td><td>${p.channel||'—'}</td><td>${esc(p.signal||'—')}</td></tr>`).join('')}</tbody></table>`}
// --- Wi-Fi channel spectrum / interference (from the passive scan) ---
async function loadSpectrum(rescan){const st=document.querySelector('#spectrumStatus');if(!st)return;st.textContent=rescan?'rescanning… (a few seconds)':'loading…';st.classList.remove('bad');try{const d=await api('/api/wifi/spectrum'+(rescan?'?rescan=1':''));renderSpectrum(d);const sp=d.spectrum||{};if(!(sp.bands||[]).length){st.textContent=d.note||'no APs visible — enable the radio and Rescan';st.classList.add('bad')}else{st.textContent=`${d.ap_count} AP(s) modelled across ${sp.bands.length} band(s) · ${fmtTs(d.ts)}`}}catch(e){st.textContent=e.message;st.classList.add('bad')}}
// Colour a 0..100 occupancy from green (clear) through amber to red (busy).
function occColor(o){o=Math.max(0,Math.min(100,o));const h=(1-o/100)*120;return `hsl(${h.toFixed(0)} 70% 45%)`}
function renderSpectrum(d){const el=document.querySelector('#spectrumChart'),rec=document.querySelector('#spectrumRec');const sp=d.spectrum||{};const bands=sp.bands||[];if(!bands.length){el.innerHTML='';rec.innerHTML='';return}
  rec.innerHTML=bands.map(b=>`<span class="chip ok" title="${esc(b.recommend.reason)}">${esc(b.band)}: ★ ch${b.recommend.channel} <span class="hint">(${b.recommend.occupancy}% busy)</span></span>`).join('')+(sp.notes||[]).map(n=>`<span class="chip">${esc(n)}</span>`).join('');
  el.innerHTML=bands.map(b=>{const W=Math.max(360,b.channels.length*26+40),H=150,padL=28,padB=22,padT=8,plot=H-padB-padT;const bw=(W-padL-8)/b.channels.length;const best=b.recommend.channel;
    const bars=b.channels.map((c,i)=>{const x=padL+i*bw,h=Math.max(1,c.occupancy/100*plot),y=padT+plot-h;const t=`${b.band} ch${c.channel} · ${c.occupancy}% busy · ${c.ap_count} AP(s)${c.dominant?' · loudest: '+c.dominant:''}`;return `<rect x="${(x+1).toFixed(1)}" y="${y.toFixed(1)}" width="${(bw-2).toFixed(1)}" height="${h.toFixed(1)}" rx="2" fill="${occColor(c.occupancy)}"><title>${esc(t)}</title></rect>`+(c.channel===best?`<text x="${(x+bw/2).toFixed(1)}" y="${(y-2).toFixed(1)}" text-anchor="middle" font-size="11" fill="var(--cyan)">★</text>`:'')}).join('');
    const labs=b.channels.map((c,i)=>{const x=padL+i*bw+bw/2;return (b.channels.length<=13||i%2===0)?`<text x="${x.toFixed(1)}" y="${(H-6)}" text-anchor="middle" font-size="8" fill="var(--muted)">${c.channel}</text>`:''}).join('');
    const grid=[0,25,50,75,100].map(v=>{const y=padT+plot-v/100*plot;return `<line x1="${padL}" y1="${y.toFixed(1)}" x2="${W-8}" y2="${y.toFixed(1)}" stroke="var(--line)" stroke-width="0.4" opacity="0.5"/><text x="2" y="${(y+3).toFixed(1)}" font-size="7" fill="var(--muted)">${v}</text>`}).join('');
    return `<div style="margin-bottom:10px"><p class="eyebrow" style="margin:2px 0"><span class="dot" style="background:${bandColor(b.band)}"></span> ${esc(b.band)}</p><svg viewBox="0 0 ${W} ${H}" style="width:100%;max-width:${W}px;display:block">${grid}${bars}${labs}</svg></div>`}).join('');}
// --- Wi-Fi roam/handover event log (colorized) ---
async function loadWifiEvents(){const st=document.querySelector('#wifiEventStatus');st.textContent='loading…';st.classList.remove('bad');try{renderWifiEvents(await api('/api/wifi/handovers?minutes=1440&limit=300'))}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderWifiEvents(d){const st=document.querySelector('#wifiEventStatus'),cEl=document.querySelector('#wifiEventCounts'),tEl=document.querySelector('#wifiEvents');const c=d.counts||{};st.textContent=`${d.total||0} event(s) over the last ${Math.round((d.window_minutes||0)/60)}h`;cEl.innerHTML=`<span class="chip"><span class="dot dot-blue"></span> ${c.info||0} info</span><span class="chip"><span class="dot dot-yellow"></span> ${c.warning||0} warning</span><span class="chip"><span class="dot dot-red"></span> ${c.error||0} error</span>`;const rows=(d.events||[]).map(e=>`<tr class="ev-${e.level}"><td>${fmtTs(e.ts)}</td><td class="lvl">${esc(e.level)}</td><td>${esc(e.kind)}</td><td>${esc(e.summary)}</td><td>${esc(e.ssid||'')}</td><td>${esc(e.bssid||'')}</td><td>${esc(e.band||'')}${e.channel?' ch'+e.channel:''}</td><td>${e.signal_dbm!=null?e.signal_dbm+' dBm':''}</td></tr>`).join('');tEl.innerHTML=`<table><thead><tr><th>Time</th><th>Level</th><th>Event</th><th>Detail</th><th>SSID</th><th>BSSID</th><th>Band/Ch</th><th>Signal</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No roam/handover events recorded yet. The monitor samples the link every 5s; events appear as the association changes.</td></tr>'}</tbody></table>`}
// --- Wi-Fi coverage heatmap / walk-around site survey ---
const HM_W=640,HM_H=440;
let hm={survey:null,apSel:'',lastClick:null,drag:null,liveTimer:null,live:null};
function hmColor(dbm){if(dbm==null)return '#334';const q=Math.max(0,Math.min(1,(dbm+90)/40));return `hsl(${Math.round(q*140)},72%,46%)`}// -90 red .. -50 green
function hmStatus(msg,bad){const el=document.querySelector('#hmStatus');if(!el)return;el.textContent=msg||'';el.classList.toggle('bad',!!bad)}
async function hmInit(){try{await hmLoadList();if(!hm.survey){const sels=document.querySelector('#hmSurvey');if(sels&&sels.value)await hmLoadSurvey(sels.value);else await hmNewSurvey('Survey 1')}else hmRender();hmToggleLive()}catch(e){hmStatus(e.message,true)}}
async function hmLoadList(){const d=await api('/api/wifi/heatmap/surveys');const sel=document.querySelector('#hmSurvey');const cur=hm.survey?String(hm.survey.id):(sel.value||'');sel.innerHTML=(d.surveys||[]).map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.point_count} pt</option>`).join('')||'<option value="">(no surveys)</option>';if(cur&&[...sel.options].some(o=>o.value===cur))sel.value=cur}
async function hmNewSurvey(preset){const name=preset||window.prompt('Name this survey (e.g. "Ground floor"):','Survey');if(!name)return;const s=await api('/api/wifi/heatmap/surveys',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await hmLoadList();document.querySelector('#hmSurvey').value=String(s.id);await hmLoadSurvey(s.id)}
async function hmRenameSurvey(){if(!hm.survey)return;const name=window.prompt('Rename survey:',hm.survey.name);if(!name)return;await api(`/api/wifi/heatmap/surveys/${hm.survey.id}/rename`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});hm.survey.name=name;await hmLoadList()}
async function hmDeleteSurvey(){if(!hm.survey)return;if(!confirm(`Delete survey "${hm.survey.name}" and all its sample points?`))return;await api(`/api/wifi/heatmap/surveys/${hm.survey.id}`,{method:'DELETE'});hm.survey=null;await hmLoadList();const sel=document.querySelector('#hmSurvey');if(sel.value)await hmLoadSurvey(sel.value);else{document.querySelector('#hmCanvas').innerHTML='';document.querySelector('#hmPoints').innerHTML=''}}
async function hmLoadSurvey(id){if(!id)return;hm.survey=await api('/api/wifi/heatmap/surveys/'+id);hmFillApSelect();hmRender()}
function hmAllAps(){const m=new Map();(hm.survey.points||[]).forEach(p=>(p.readings||[]).forEach(r=>{if(r.bssid&&!m.has(r.bssid))m.set(r.bssid,r.ssid||'(hidden)')}));Object.entries(hm.survey.ap_positions||{}).forEach(([b,pos])=>{if(!m.has(b))m.set(b,pos.ssid||'(hidden)')});return m}
function hmFillApSelect(){const sel=document.querySelector('#hmApSelect');const aps=hm.allAps=hmAllAps();const prev=hm.apSel;sel.innerHTML=[...aps.entries()].map(([b,s])=>`<option value="${esc(b)}">${esc(s)} · ${esc(b)}</option>`).join('')||'<option value="">(sample some points first)</option>';if(prev&&aps.has(prev))sel.value=prev;hm.apSel=sel.value}
function hmFrac(evt){const svg=document.querySelector('#hmCanvas');const r=svg.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(evt.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(evt.clientY-r.top)/r.height))}}
function hmCanvasClick(evt){if(document.querySelector('#hmMode').checked)return;hm.lastClick=hmFrac(evt);hmRender()}
function hmModeChange(){document.querySelector('#hmCanvas').style.cursor=document.querySelector('#hmMode').checked?'move':'crosshair';hmStatus(document.querySelector('#hmMode').checked?'Drag AP markers (▲) to their real-world position. Uncheck to sample again.':'')}
async function hmSampleLast(){if(!hm.survey){hmStatus('Create or select a survey first',true);return}if(!hm.lastClick){hmStatus('Click your position on the floor first, then Sample here',true);return}hmStatus('scanning at this position…');try{const r=await api(`/api/wifi/heatmap/surveys/${hm.survey.id}/sample`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({x:hm.lastClick.x,y:hm.lastClick.y,rescan:true})});hmStatus(`captured ${(r.point.readings||[]).length} AP reading(s)${r.note?' — '+r.note:''}`);await hmLoadSurvey(hm.survey.id);await hmLoadList()}catch(e){hmStatus(e.message,true)}}
async function hmDeletePoint(pid){if(!hm.survey)return;await api(`/api/wifi/heatmap/surveys/${hm.survey.id}/points/${pid}`,{method:'DELETE'});await hmLoadSurvey(hm.survey.id);await hmLoadList()}
function hmRender(){const svg=document.querySelector('#hmCanvas');if(!svg||!hm.survey)return;hm.apSel=document.querySelector('#hmApSelect').value;const pts=hm.survey.points||[];const sel=hm.apSel;
  // gather readings for the selected AP
  const samples=pts.map(p=>{const rd=(p.readings||[]).find(r=>r.bssid===sel);return rd&&rd.signal_dbm!=null?{x:p.x,y:p.y,dbm:rd.signal_dbm}:null}).filter(Boolean);
  let cells='';const COLS=40,ROWS=28,cw=HM_W/COLS,ch=HM_H/ROWS;
  if(samples.length){for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){const fx=(c+0.5)/COLS,fy=(r+0.5)/ROWS;let num=0,den=0,near=9;samples.forEach(s=>{const dx=s.x-fx,dy=s.y-fy;const d=Math.sqrt(dx*dx+dy*dy);near=Math.min(near,d);const w=1/Math.max(d*d,1e-4);num+=w*s.dbm;den+=w});const val=num/den;const alpha=Math.max(0.05,Math.min(0.72,1.15-near*3.2));cells+=`<rect x="${(c*cw).toFixed(1)}" y="${(r*ch).toFixed(1)}" width="${cw.toFixed(1)}" height="${ch.toFixed(1)}" fill="${hmColor(val)}" opacity="${alpha.toFixed(2)}"/>`}}
  // sample point dots
  let dots=pts.map(p=>{const rd=(p.readings||[]).find(r=>r.bssid===sel);const t=rd&&rd.signal_dbm!=null?`${rd.signal_dbm} dBm`:'no reading';return `<circle cx="${(p.x*HM_W).toFixed(1)}" cy="${(p.y*HM_H).toFixed(1)}" r="4" fill="#0a0f14" stroke="var(--text)" stroke-width="1"><title>${(p.readings||[]).length} APs · ${esc(t)}</title></circle>`}).join('');
  // AP markers (draggable in place-mode)
  const aps=hm.survey.ap_positions||{};let marks='';for(const [b,pos] of Object.entries(aps)){const x=pos.x*HM_W,y=pos.y*HM_H;const on=b===sel;marks+=`<g onmousedown="hmApDown('${esc(b)}',event)" style="cursor:move"><polygon points="${x.toFixed(1)},${(y-9).toFixed(1)} ${(x-8).toFixed(1)},${(y+6).toFixed(1)} ${(x+8).toFixed(1)},${(y+6).toFixed(1)}" fill="${on?'var(--cyan)':'var(--amber)'}" stroke="#0a0f14" stroke-width="1"/><text x="${x.toFixed(1)}" y="${(y+20).toFixed(1)}" text-anchor="middle" font-size="9" fill="${on?'var(--cyan)':'var(--muted)'}">${esc(pos.ssid||b.slice(-5))}</text></g>`}
  // "you are here"
  let here='';if(hm.lastClick){const x=hm.lastClick.x*HM_W,y=hm.lastClick.y*HM_H;here=`<g><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="7" fill="none" stroke="var(--text)" stroke-width="1.5"/><line x1="${(x-11).toFixed(1)}" y1="${y.toFixed(1)}" x2="${(x+11).toFixed(1)}" y2="${y.toFixed(1)}" stroke="var(--text)"/><line x1="${x.toFixed(1)}" y1="${(y-11).toFixed(1)}" x2="${x.toFixed(1)}" y2="${(y+11).toFixed(1)}" stroke="var(--text)"/></g>`}
  svg.innerHTML=`<rect width="${HM_W}" height="${HM_H}" fill="#0a0f14"/>${cells}${dots}${marks}${here}${samples.length?'':'<text x="'+HM_W/2+'" y="'+HM_H/2+'" text-anchor="middle" fill="#5b6b7a" font-size="12">Click a spot, then “Sample here”, to build the heatmap</text>'}`;
  svg.onclick=hmCanvasClick;
  // points table + scale
  document.querySelector('#hmPoints').innerHTML=pts.length?`<table><thead><tr><th>#</th><th>When</th><th>APs</th><th>Sel dBm</th><th></th></tr></thead><tbody>${pts.map((p,i)=>{const rd=(p.readings||[]).find(r=>r.bssid===sel);return `<tr><td>${i+1}</td><td>${fmtTs(p.ts)}</td><td>${(p.readings||[]).length}</td><td>${rd&&rd.signal_dbm!=null?rd.signal_dbm:'—'}</td><td><button onclick="hmDeletePoint(${p.id})">✕</button></td></tr>`}).join('')}</tbody></table>`:'<p class="hint">No sample points yet.</p>';
  document.querySelector('#hmScale').innerHTML=[-50,-60,-70,-80,-90].map(d=>`<span class="chip"><span class="dot" style="background:${hmColor(d)}"></span> ${d} dBm</span>`).join('');
}
function hmApDown(bssid,evt){if(!document.querySelector('#hmMode').checked)return;evt.preventDefault();evt.stopPropagation();hm.drag=bssid;const move=e=>{const f=hmFrac(e);hm.survey.ap_positions[bssid]={...(hm.survey.ap_positions[bssid]||{}),x:f.x,y:f.y};hmRender()};const up=async()=>{window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);hm.drag=null;try{await api(`/api/wifi/heatmap/surveys/${hm.survey.id}/ap-positions`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({positions:hm.survey.ap_positions})});hmStatus('AP position saved')}catch(e){hmStatus(e.message,true)}};window.addEventListener('mousemove',move);window.addEventListener('mouseup',up)}
// place an AP marker for the currently-selected AP at the last click (helper when it has no position yet)
function hmPlaceSelected(){if(!hm.survey||!hm.apSel||!hm.lastClick)return;const ssid=(hm.allAps&&hm.allAps.get(hm.apSel))||'';hm.survey.ap_positions[hm.apSel]={x:hm.lastClick.x,y:hm.lastClick.y,ssid};api(`/api/wifi/heatmap/surveys/${hm.survey.id}/ap-positions`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({positions:hm.survey.ap_positions})}).then(()=>{hmStatus('placed '+ssid);hmRender()})}
function hmToggleLive(){if(hm.liveTimer){clearInterval(hm.liveTimer);hm.liveTimer=null}if(document.querySelector('#hmLive').checked){hmLiveTick();hm.liveTimer=setInterval(hmLiveTick,5000)}else document.querySelector('#hmLiveMeter').innerHTML=''}
async function hmLiveTick(){if(!document.querySelector('#heatmap').classList.contains('active')){if(hm.liveTimer){clearInterval(hm.liveTimer);hm.liveTimer=null}return}try{const d=await api('/api/wifi/heatmap/live');hm.live=d;const conn=(d.readings||[]).find(r=>r.in_use);const selR=(d.readings||[]).find(r=>r.bssid===hm.apSel);const chips=[];if(conn)chips.push(`<span class="chip"><span class="dot" style="background:${hmColor(conn.signal_dbm)}"></span> connected: ${esc(conn.ssid)} ${conn.signal_dbm!=null?conn.signal_dbm+' dBm':''}</span>`);if(selR&&(!conn||selR.bssid!==conn.bssid))chips.push(`<span class="chip"><span class="dot" style="background:${hmColor(selR.signal_dbm)}"></span> selected AP: ${selR.signal_dbm!=null?selR.signal_dbm+' dBm':'—'}</span>`);chips.push(`<span class="chip">${(d.readings||[]).length} AP(s) heard</span>`);document.querySelector('#hmLiveMeter').innerHTML=chips.join('')}catch(e){document.querySelector('#hmLiveMeter').innerHTML=`<span class="chip warn">live: ${esc(e.message)}</span>`}}
function hmExportPng(){const svg=document.querySelector('#hmCanvas');if(!svg)return;const xml=new XMLSerializer().serializeToString(svg);const img=new Image();const blob=new Blob([xml],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);img.onload=()=>{const cv=document.createElement('canvas');cv.width=HM_W*2;cv.height=HM_H*2;const cx=cv.getContext('2d');cx.fillStyle='#0a0f14';cx.fillRect(0,0,cv.width,cv.height);cx.drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(url);cv.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`heatmap-${(hm.survey&&hm.survey.name||'survey').replace(/\W+/g,'_')}.png`;a.click()})};img.onerror=()=>{URL.revokeObjectURL(url);toast('PNG export failed')};img.src=url}
function sevClass(s){return s==='critical'||s==='major'?'bad':(s==='minor'?'warn':'ok')}
const fmtTs=t=>t?new Date(t*1000).toLocaleString():'—';
const fmtAge=s=>s==null?'—':(s<90?s+'s':(s<5400?Math.round(s/60)+'m':Math.round(s/3600)+'h'))+' ago';
// --- Overview: anomalies + data freshness ---
async function loadAttention(){let fresh,anom;try{[fresh,anom]=await Promise.all([api('/api/health/freshness'),api('/api/anomalies')])}catch(e){document.querySelector('#attention').innerHTML=`<p class="hint bad">${esc(e.message)}</p>`;return}
  document.querySelector('#freshness').innerHTML=(fresh.sources||[]).map(s=>{const cls=!s.present?'':(s.stale?'bad':'ok');const age=s.present?fmtAge(s.age_seconds):'absent';return `<span class="chip ${cls}" title="${esc(s.note||'')} (stale after ${s.threshold}s)">${esc(s.source)} · ${age}</span>`}).join('');
  const items=anom.anomalies||[];const lvl=l=>l==='critical'?'bad':(l==='warning'?'warn':'ok');
  document.querySelector('#attention').innerHTML=items.length?`<ul class="attn-list">${items.map(a=>`<li class="attn ${lvl(a.level)}"><span class="chip ${lvl(a.level)}">${esc(a.level)}</span> <strong>${esc(a.message)}</strong>${a.detail?`<div class="hint">${esc(a.detail)}</div>`:''}</li>`).join('')}</ul>`:'<p class="hint ok">Nothing needs attention right now — no stale feeds, open outages, or high-severity alerts.</p>'}
// --- Actions: custom-target service catalog ---
let catalog={services:[]};
async function loadCatalog(force){if(catalog.services.length&&!force)return;try{catalog=await api('/api/services/catalog')}catch(e){return}
  const grp=(cat,label)=>{const o=catalog.services.filter(s=>s.category===cat).map(s=>`<option value="${esc(s.name)}" data-port="${s.port}" data-proto="${esc(s.proto)}" data-cat="${esc(cat)}">${esc(s.name)} · ${s.port}/${esc(s.proto)}</option>`).join('');return o?`<optgroup label="${label}">${o}</optgroup>`:''};
  document.querySelector('#actService').innerHTML=`<option value="">— known service (optional) —</option>`+grp('custom','Custom (saved)')+grp('it','IT / infrastructure')+grp('ot','OT / ICS (change window only)')}
function actServicePick(){const sel=document.querySelector('#actService'),opt=sel.options[sel.selectedIndex];if(opt&&opt.dataset.port)document.querySelector('#actPort').value=opt.dataset.port}
function actTargets(){const ip=document.querySelector('#actIp').value.trim();const port=document.querySelector('#actPort').value.trim();return{ip,port}}
async function actJob(url,payload,label,render){const st=document.querySelector('#actStatus'),res=document.querySelector('#actResult');st.textContent=label+'…';st.classList.remove('bad');res.innerHTML='';try{const started=await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const{data,job}=await pollJob(started.job_id);st.textContent=label+' complete';res.innerHTML=render(data,job);loadJobs()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function actReachability(){const{ip,port}=actTargets();if(!ip||!port){toast('enter an IP and port');return}actJob('/api/actions/reachability',{ip,port:+port},`TCP reachability ${ip}:${port}`,(d,job)=>`<pre>${esc((job&&job.output)||(d&&d.raw)||'no output')}</pre>`)}
function actServiceHealth(){const{ip,port}=actTargets();if(!ip){toast('enter a host (IP or name)');return}const p=port||'443';actJob('/api/actions/service-health',{host:ip,port:+p},`Service health ${ip}:${p}`,d=>renderServiceHealth(d))}
function renderServiceHealth(d){if(!d||d.raw)return `<pre>${esc((d&&d.raw)||'no output')}</pre>`;const ok=b=>b?'<span class="chip ok">ok</span>':'<span class="chip bad">fail</span>';const rows=[];const dns=d.dns||{};rows.push(`<tr><td>DNS</td><td>${ok(dns.ok)}</td><td>${dns.ok?esc((dns.answers||[]).join(', ')||'—')+(dns.time_ms!=null?` · ${dns.time_ms} ms`:'')+(dns.server?` · via ${esc(dns.server)}`:''):esc(dns.error||'')}</td></tr>`);const c=d.clock||{};rows.push(`<tr><td>Clock/NTP</td><td>${ok(c.ok)}</td><td>${c.ok?`stratum ${esc(c.stratum||'?')} · offset ${c.last_offset_s!=null?c.last_offset_s+' s':'?'} · ref ${esc(c.reference||'—')} · ${esc(c.leap||'')}`:esc(c.error||'')}</td></tr>`);const t=d.tcp||{};rows.push(`<tr><td>TCP :${d.port}</td><td>${ok(t.open)}</td><td>${t.open?`connect ${t.connect_ms} ms`:esc(t.error||'closed')}</td></tr>`);if(d.tls){const s=d.tls;rows.push(`<tr><td>TLS</td><td>${ok(s.ok)}</td><td>${s.ok?`${esc(s.version||'')} · ${esc(s.cipher||'')}<br>subject ${esc(s.subject||'—')}<br>issuer ${esc(s.issuer||'—')}<br>expires ${esc(s.not_after||'?')}${s.days_left!=null?` (${s.days_left} d)`:''}${(s.sans&&s.sans.length)?`<br>SAN: ${s.sans.map(esc).join(', ')}`:''}`:esc(s.error||'')}</td></tr>`)}if(d.http){const h=d.http,tm=h.times_ms||{};rows.push(`<tr><td>HTTP</td><td>${ok(h.ok)}</td><td>${h.ok?`status ${esc(h.status)} · ${esc(h.url)}${h.redirect?` → ${esc(h.redirect)}`:''}<br>dns ${tm.dns} · connect ${tm.connect} · tls ${tm.tls} · ttfb ${tm.ttfb} · total ${tm.total} ms`:esc(h.error||'')}</td></tr>`)}return `<table><thead><tr><th>Check</th><th></th><th>Detail</th></tr></thead><tbody>${rows.join('')}</tbody></table>`}
function actTrace(){const{ip}=actTargets();if(!ip){toast('enter an IP');return}actJob('/api/trace-ip',{ip},`Trace ${ip}`,(d,job)=>`<pre>${esc((job&&job.output)||(d&&d.raw)||'no output')}</pre>`)}
function actSnmp(){const{ip}=actTargets();if(!ip){toast('enter an IP');return}actJob('/api/snmp',{ip,walk_interfaces:true},`SNMP ${ip}`,d=>{if(!d||d.status!=='ok')return `<p class="hint bad">${esc((d&&(d.note||d.status))||'no result')}</p>`;const sys=d.system||{};const rows=Object.entries(sys).filter(([,v])=>v).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('');const ifs=(d.interfaces||[]).length?`<p class="hint">Interfaces: ${d.interfaces.map(esc).join(', ')}</p>`:'';return `<table><thead><tr><th>OID</th><th>Value</th></tr></thead><tbody>${rows||'<tr><td colspan="2">no values</td></tr>'}</tbody></table>${ifs}`})}
async function actAddScope(){const{ip,port}=actTargets();if(!ip||!port){toast('enter an IP and port');return}const sel=document.querySelector('#actService'),opt=sel.options[sel.selectedIndex];const proto=(opt&&opt.value)?(opt.dataset.cat==='custom'?(opt.dataset.proto||'tcp'):opt.value):'tcp';try{const r=await api('/api/scope/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address:ip,port:+port,protocol:proto,name:'host-'+ip})});toast(r.status==='exists'?`${ip}:${port} already in scope`:`Added ${ip}:${port} to approved scope`);refresh()}catch(e){toast(e.message)}}
async function actAddMonitor(){const{ip,port}=actTargets();if(!ip||!port){toast('enter an IP and port');return}const sel=document.querySelector('#actService'),opt=sel.options[sel.selectedIndex];const proto=(opt&&opt.dataset.proto)?opt.dataset.proto:'tcp';try{const r=await api('/api/traffic/allow/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({host:ip,port:+port,proto})});toast(r.status==='exists'?`${ip}:${port}/${proto} already allow-listed`:`Allow-listed ${ip}:${port}/${proto} for traffic generation`);loadTrafficAllow()}catch(e){toast(e.message)}}
// --- Traffic generator ---
function tgSend(){const host=document.querySelector('#tgHost').value.trim(),port=document.querySelector('#tgPort').value.trim();if(!host||!port){toast('enter host and port');return}const st=document.querySelector('#tgStatus');const data=document.querySelector('#tgData').value;const payload={host,port:+port,proto:document.querySelector('#tgProto').value,count:+document.querySelector('#tgCount').value,rate:+document.querySelector('#tgRate').value};if(data)payload.data=data;st.textContent='sending…';st.classList.remove('bad');api('/api/traffic/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(r=>{st.textContent='job '+r.job_id+' started';loadJobs()}).catch(e=>{st.textContent=e.message;st.classList.add('bad')})}
async function tgAllowAdd(){const host=document.querySelector('#tgAllowHost').value.trim(),port=document.querySelector('#tgAllowPort').value.trim();if(!host||!port){toast('enter host and port');return}try{const r=await api('/api/traffic/allow/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({host,port:+port,proto:document.querySelector('#tgAllowProto').value})});toast(r.status==='exists'?'already allow-listed':'added to allow-list');document.querySelector('#tgAllowHost').value='';document.querySelector('#tgAllowPort').value='';loadTrafficAllow()}catch(e){toast(e.message)}}
async function tgAllowRemove(host,port,proto){if(!confirm(`Remove ${host}:${port}/${proto} from the traffic allow-list?`))return;try{await api('/api/traffic/allow/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({host,port:+port,proto})});toast('removed');loadTrafficAllow()}catch(e){toast(e.message)}}
async function loadTrafficAllow(){let list;try{list=await api('/api/traffic/allow')}catch(e){return}
  const rows=list.map(e=>`<tr><td>${ipLink(e.host)}</td><td>${e.port}</td><td>${esc(e.proto)}</td><td>${esc(e.source||'file')}</td><td>${e.source==='dashboard'?`<button onclick="tgAllowRemove('${esc(e.host)}',${e.port},'${esc(e.proto)}')">Remove</button>`:'<span class="hint">read-only</span>'}</td></tr>`).join('');
  document.querySelector('#tgAllowList').innerHTML=`<table><thead><tr><th>Host</th><th>Port</th><th>Proto</th><th>Source</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="5">No allow-listed destinations yet. Add one above to enable traffic generation.</td></tr>'}</tbody></table>`}
// --- Assets: observed hosts + scan history ---
async function loadAssets(){let hosts,scans;try{[hosts,scans]=await Promise.all([api('/api/hosts'),api('/api/scans?limit=200')])}catch(e){document.querySelector('#assetsResult').innerHTML=`<p class="hint bad">${esc(e.message)}</p>`;return}
  const hrows=hosts.map(h=>`<tr onclick="showHost('${esc(h.address)}')" class="clickrow" title="Per-host history"><td>${ipLink(h.address)}</td><td>${esc(h.name||'')}</td><td>${esc(h.vendor||'')}</td><td>${esc(h.mac||'')}</td><td>${(h.sources||[]).map(s=>`<span class="chip">${esc(s)}</span>`).join(' ')}</td><td>${fmtTs(h.last_seen)}</td></tr>`).join('');
  document.querySelector('#assetsResult').innerHTML=`<table><thead><tr><th>Address</th><th>Name</th><th>Vendor</th><th>MAC</th><th>Seen by</th><th>Last seen</th></tr></thead><tbody>${hrows||'<tr><td colspan="6">No hosts recorded yet. Run discovery, a reachability check or an SNMP probe.</td></tr>'}</tbody></table>`;
  const okc=v=>v==null?'':(v?'ok':'bad');const okt=v=>v==null?'·':(v?'ok':'fail');
  const srows=scans.map(s=>`<tr><td>${fmtTs(s.ts)}</td><td>${esc(s.kind)}</td><td>${ipLink(s.target)}</td><td class="${okc(s.ok)}">${okt(s.ok)}</td><td>${esc(s.summary||'')}</td></tr>`).join('');
  document.querySelector('#scanLog').innerHTML=`<table><thead><tr><th>Time</th><th>Action</th><th>Target</th><th>OK</th><th>Summary</th></tr></thead><tbody>${srows||'<tr><td colspan="5">No actions logged yet.</td></tr>'}</tbody></table>`}
async function showHost(address){let h;try{h=await api('/api/hosts/'+encodeURIComponent(address))}catch(e){toast(e.message);return}
  document.querySelector('#alertDetailTitle').textContent='Host '+address;
  const meta=`<div class="chips"><span class="chip">first seen ${fmtTs(h.first_seen)}</span><span class="chip">last seen ${fmtTs(h.last_seen)}</span>${h.vendor?`<span class="chip">${esc(h.vendor)}</span>`:''}${h.mac?`<span class="chip">${esc(h.mac)}</span>`:''}${(h.sources||[]).map(s=>`<span class="chip ok">${esc(s)}</span>`).join('')}</div>`;
  const okt=v=>v==null?'·':(v?'ok':'fail');const okc=v=>v==null?'':(v?'ok':'bad');
  const rows=(h.scans||[]).map(s=>`<tr><td>${fmtTs(s.ts)}</td><td>${esc(s.kind)}</td><td class="${okc(s.ok)}">${okt(s.ok)}</td><td>${esc(s.summary||'')}</td></tr>`).join('');
  document.querySelector('#alertDetailBody').innerHTML=meta+`<table><thead><tr><th>Time</th><th>Action</th><th>OK</th><th>Summary</th></tr></thead><tbody>${rows||'<tr><td colspan="4">no recorded actions</td></tr>'}</tbody></table><div class="form-row" style="margin-top:.6rem"><button onclick="document.querySelector('#actIp').value='${esc(address)}';document.querySelector('#alertDetail').style.display='none';document.querySelector('nav button[data-view=actions]').click()">Use in Actions</button></div>`;
  document.querySelector('#alertDetail').style.display='flex'}
// --- Suricata alert drill-down ---
async function showAlert(flowId){const box=document.querySelector('#alertDetail');document.querySelector('#alertDetailTitle').textContent='Alert · flow '+flowId;document.querySelector('#alertDetailBody').innerHTML='<p class="hint">loading…</p>';box.style.display='flex';let d;try{d=await api('/api/ids/alert?flow='+encodeURIComponent(flowId))}catch(e){document.querySelector('#alertDetailBody').innerHTML=`<p class="hint bad">${esc(e.message)}</p>`;return}
  if(d.status!=='ok'){document.querySelector('#alertDetailBody').innerHTML=`<p class="hint bad">${esc(d.note||d.status||'no events for this flow')}</p>`;return}
  const al=d.alert||{},a=al.alert||{};
  let head='';if(a.signature){head=`<div class="chips"><span class="chip ${a.severity<=2?'bad':(a.severity===3?'warn':'ok')}">severity ${esc(a.severity)}</span>${a.category?`<span class="chip">${esc(a.category)}</span>`:''}${a.signature_id?`<span class="chip">SID ${esc(a.signature_id)}</span>`:''}</div><p><strong>${esc(a.signature)}</strong></p><p class="hint">${ipLinkRaw(al.src_ip)}${al.src_port?':'+al.src_port:''} → ${ipLinkRaw(al.dest_ip)}${al.dest_port?':'+al.dest_port:''} · ${esc(al.proto||'')}${al.app_proto?' · '+esc(al.app_proto):''} · ${esc((al.timestamp||'').slice(0,19).replace('T',' '))}</p>`}
  const types=`<p class="hint">${d.count} correlated event(s): ${(d.event_types||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join(' ')}</p>`;
  const evs=(d.events||[]).map(renderEve).join('');
  document.querySelector('#alertDetailBody').innerHTML=head+types+evs+`<details style="margin-top:.6rem"><summary class="hint">Raw JSON (all ${d.count} events)</summary><pre>${esc(JSON.stringify(d.events,null,2))}</pre></details>`}
// Render one EVE event with all the detail Suricata carries for its type.
function eveKV(obj,keys){return keys.filter(k=>obj[k]!=null&&obj[k]!=='').map(k=>`<tr><td>${esc(k)}</td><td>${esc(obj[k])}</td></tr>`).join('')}
function eveHeaders(list){return Array.isArray(list)&&list.length?`<div class="table-wrap"><table><tbody>${list.map(h=>`<tr><td>${esc(h.name||'')}</td><td>${esc(h.value||'')}</td></tr>`).join('')}</tbody></table></div>`:''}
function renderEve(e){const t=e.event_type||'';let inner='';
  if(t==='http'&&e.http){const h=e.http;inner=`<table><tbody>${eveKV(h,['http_method','hostname','url','protocol','status','length','http_user_agent','http_refer','http_content_type','redirect','http_port'])}</tbody></table>`;if(h.request_headers&&h.request_headers.length)inner+=`<details><summary class="hint">request headers (${h.request_headers.length})</summary>${eveHeaders(h.request_headers)}</details>`;if(h.response_headers&&h.response_headers.length)inner+=`<details><summary class="hint">response headers (${h.response_headers.length})</summary>${eveHeaders(h.response_headers)}</details>`;if(h.http_request_body_printable)inner+=`<details><summary class="hint">request body (POST content)</summary><pre>${esc(h.http_request_body_printable)}</pre></details>`;if(h.http_response_body_printable)inner+=`<details><summary class="hint">response body</summary><pre>${esc(h.http_response_body_printable)}</pre></details>`;}
  else if(t==='dns'&&e.dns){const dn=e.dns;const ans=(dn.answers||[]).map(a=>esc(`${a.rrname||''} ${a.rrtype||''} ${a.rdata||a.rdata_ip||''}`)).join('<br>');inner=`<table><tbody>${eveKV(dn,['type','rrname','rrtype','rcode','tx_id'])}</tbody></table>${ans?`<div class="hint" style="margin-top:.4rem">answers:<br>${ans}</div>`:''}`;}
  else if(t==='tls'&&e.tls){inner=`<table><tbody>${eveKV(e.tls,['sni','version','subject','issuerdn','serial','fingerprint','notbefore','notafter','ja3','ja3s'])}</tbody></table>`;}
  else if(t==='fileinfo'&&e.fileinfo){inner=`<table><tbody>${eveKV(e.fileinfo,['filename','magic','mimetype','size','md5','sha256','state','stored'])}</tbody></table>`;}
  else if(t==='flow'&&e.flow){inner=`<table><tbody>${eveKV(e.flow,['pkts_toserver','pkts_toclient','bytes_toserver','bytes_toclient','start','end','age','state','reason'])}</tbody></table>`;}
  else if(t==='alert'&&e.alert){inner=`<table><tbody>${eveKV(e.alert,['signature','category','severity','signature_id','gid','rev'])}</tbody></table>`;}
  else{inner=`<pre>${esc(JSON.stringify(e[t]||e,null,2))}</pre>`;}
  const five=e.src_ip?`<span class="hint"> ${esc(e.src_ip)}${e.src_port?':'+e.src_port:''} → ${esc(e.dest_ip||'')}${e.dest_port?':'+e.dest_port:''}</span>`:'';
  return `<details ${t==='http'||t==='alert'?'open':''} style="margin-top:.5rem"><summary><strong>${esc(t)}</strong> <span class="hint">${esc((e.timestamp||'').slice(11,19))}</span>${five}</summary>${inner}</details>`}
function ipLinkRaw(ip){return ip?`<a href="#" class="iplink" onclick="showIp('${esc(ip)}');return false">${esc(ip)}</a>`:'—'}
// --- IP dossier: everything the probe knows about one address ---------------
async function showIp(ip){const box=document.querySelector('#alertDetail');document.querySelector('#alertDetailTitle').textContent='IP · '+ip;document.querySelector('#alertDetailBody').innerHTML='<p class="hint">loading…</p>';box.style.display='flex';let d;try{d=await api('/api/ip/'+encodeURIComponent(ip))}catch(e){document.querySelector('#alertDetailBody').innerHTML=`<p class="hint bad">${esc(e.message)}</p>`;return}
  const h=d.host;const chips=[];if(d.reverse_dns)chips.push(`<span class="chip">${esc(d.reverse_dns)}</span>`);if(d.is_local)chips.push(`<span class="chip ok">local · ${(d.local_interfaces||[]).map(esc).join(', ')}</span>`);if(h){chips.push(`<span class="chip">first seen ${fmtTs(h.first_seen)}</span>`,`<span class="chip">last seen ${fmtTs(h.last_seen)}</span>`);if(h.vendor)chips.push(`<span class="chip">${esc(h.vendor)}</span>`);if(h.mac)chips.push(`<span class="chip">${esc(h.mac)}</span>`);(h.sources||[]).forEach(s=>chips.push(`<span class="chip ok">${esc(s)}</span>`));}
  const actions=`<div class="form-row" style="margin-top:.5rem"><button onclick="ipAction('${esc(ip)}','trace')">Trace route</button><button onclick="ipAction('${esc(ip)}','snmp')">SNMP</button><button onclick="ipReach('${esc(ip)}')">TCP reachability…</button><button onclick="document.querySelector('#actIp').value='${esc(ip)}';document.querySelector('#alertDetail').style.display='none';document.querySelector('nav button[data-view=actions]').click()">Open in Actions</button></div><div id="ipActStatus" class="hint"></div><pre id="ipActOut" style="display:none"></pre>`;
  let sections='';const memb=[];if((d.scope||[]).length)memb.push(`approved scope: ${d.scope.map(s=>esc(s.name)+' ('+s.port+'/'+esc(s.protocol)+')').join(', ')}`);if((d.traffic_allow||[]).length)memb.push(`traffic allow-list: ${d.traffic_allow.map(a=>a.port+'/'+esc(a.proto)).join(', ')}`);if(memb.length)sections+=`<p class="hint">${memb.join(' · ')}</p>`;
  if(d.monitor){const m=d.monitor;sections+=`<p class="hint">Outage monitor: ${m.up?'<span class="ok">up</span>':'<span class="bad">down</span>'} · ${m.loss_pct_24h}% loss/24h${m.rtt_avg_ms!=null?' · '+m.rtt_avg_ms+' ms avg':''} · last ${fmtTs(m.last_seen)}</p>`;}
  if((d.lldp||[]).length){sections+=`<h2 style="margin-top:.8rem">Neighbour (LLDP)</h2>`+d.lldp.map(n=>`<p class="hint">${esc(n.system||'')} · port ${esc(n.port_id||'')}${n.port_descr?' ('+esc(n.port_descr)+')':''} · vlan ${esc(n.vlan||'')} · local ${esc(n.local_port||'')}</p>`).join('');}
  const ids=d.ids||{};if((ids.alerts||[]).length){sections+=`<h2 style="margin-top:.8rem">IDS alerts (${ids.as_src} as source · ${ids.as_dst} as destination)</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Sev</th><th>Signature</th><th>Src → Dst</th><th></th></tr></thead><tbody>`+ids.alerts.map(a=>`<tr><td>${esc(a.time)}</td><td class="${sevClass(a.severity_label)}">${esc(a.severity_label)}</td><td>${esc(a.signature)}</td><td>${esc(a.src||'')}${a.sport?':'+a.sport:''} → ${esc(a.dst||'')}${a.dport?':'+a.dport:''}</td><td>${a.flow_id?`<button onclick="showAlert('${esc(a.flow_id)}')">Details</button>`:''}</td></tr>`).join('')+`</tbody></table></div>`;}
  const okt=v=>v==null?'·':(v?'ok':'fail'),okc=v=>v==null?'':(v?'ok':'bad');
  if(h&&(h.scans||[]).length){sections+=`<h2 style="margin-top:.8rem">Action history</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>OK</th><th>Summary</th></tr></thead><tbody>`+h.scans.map(s=>`<tr><td>${fmtTs(s.ts)}</td><td>${esc(s.kind)}</td><td class="${okc(s.ok)}">${okt(s.ok)}</td><td>${esc(s.summary||'')}</td></tr>`).join('')+`</tbody></table></div>`;}
  if(!h&&!(ids.alerts||[]).length&&!d.monitor&&!(d.lldp||[]).length&&!memb.length)sections+='<p class="hint">Nothing recorded for this IP yet. Use the actions above to gather trace / SNMP / reachability data.</p>';
  document.querySelector('#alertDetailBody').innerHTML=(chips.length?`<div class="chips">${chips.join('')}</div>`:'')+actions+sections}
async function ipAction(ip,kind){const st=document.querySelector('#ipActStatus'),out=document.querySelector('#ipActOut');st.textContent='running…';out.style.display='none';try{const url=kind==='snmp'?'/api/snmp':'/api/trace-ip';const payload=kind==='snmp'?{ip,walk_interfaces:true}:{ip};const started=await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const{data,job}=await pollJob(started.job_id);st.textContent='';out.style.display='block';out.textContent=(job&&job.output)||(data&&data.raw)||JSON.stringify(data,null,2)||'no output';loadJobs()}catch(e){st.textContent=e.message}}
async function ipReach(ip){const port=window.prompt('TCP port to check on '+ip+':','443');if(!port)return;const st=document.querySelector('#ipActStatus'),out=document.querySelector('#ipActOut');st.textContent='checking…';out.style.display='none';try{const started=await api('/api/actions/reachability',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ip,port:+port})});const{data,job}=await pollJob(started.job_id);st.textContent='';out.style.display='block';out.textContent=(job&&job.output)||(data&&data.raw)||'no output';loadJobs()}catch(e){st.textContent=e.message}}
// --- Network (IPv4) via the privileged reconciler + auto-rollback -----------
let netState=null,netTick=null;
function netMethodToggle(){document.querySelector('#netManual').style.display=document.querySelector('#netMethod').value==='manual'?'block':'none'}
async function loadNetwork(){let d;try{d=await api('/api/network')}catch(e){document.querySelector('#netStatus').innerHTML=`<span class="bad">${esc(e.message)}</span>`;return}netState=d;
  const sel=document.querySelector('#netIface');const cur=sel.value;
  sel.innerHTML=(d.interfaces||[]).map(i=>`<option value="${esc(i.name)}">${esc(i.name)}${i.wired?' · wired':' · wireless'}${i.up?'':' (down)'}${i.addresses?' · '+esc(i.addresses):''}</option>`).join('')||'<option value="">no interfaces</option>';
  if(cur)sel.value=cur;
  netMethodToggle();renderNetwork(d)}
function renderNetwork(d){const pend=document.querySelector('#netPending'),live=document.querySelector('#netLive');const st=d.state||{};
  // Live device state reported by the reconciler's applier, if any.
  const actual=st.actual&&st.actual.devices?st.actual.devices:null;
  live.innerHTML=actual?('<strong>Live:</strong> '+actual.map(x=>`${esc(x.device)} <span class="hint">${esc(x.state)}${x.connection&&x.connection!=='--'?' · '+esc(x.connection):''}</span>`).join(' &nbsp;·&nbsp; ')):(st.status&&st.status!=='none'?`<span class="hint">last result: ${esc(st.status)} — ${esc(st.detail||'')}</span>`:'');
  if(netTick){clearInterval(netTick);netTick=null}
  if(d.awaiting_confirm){let left=d.seconds_left||0;const draw=()=>{pend.innerHTML=`<div class="panel" style="border-left:4px solid var(--warn,#e0a800);padding:.6rem"><strong class="warn">Change is live — awaiting your confirmation.</strong> Reverts automatically in <strong id="netCountdown">${left}</strong>s if you don't keep it. <button class="primary" onclick="confirmNetwork()">Keep this change</button></div>`};draw();
    netTick=setInterval(async()=>{left--;const c=document.querySelector('#netCountdown');if(c)c.textContent=left;if(left<=0){clearInterval(netTick);netTick=null;setTimeout(loadNetwork,1500)}},1000)}
  else{pend.innerHTML=st.status==='rolled_back'?'<span class="bad">Previous change was not confirmed in time and was rolled back.</span>':(st.status==='applied'?'<span class="ok">Applied and confirmed.</span>':'')}}
async function applyNetwork(){const method=document.querySelector('#netMethod').value;const payload={interface:document.querySelector('#netIface').value,method,grace_seconds:+document.querySelector('#netGrace').value||120};
  if(method==='manual'){payload.address=document.querySelector('#netAddress').value.trim();payload.prefix=+document.querySelector('#netPrefix').value||24;const gw=document.querySelector('#netGateway').value.trim();if(gw)payload.gateway=gw;const dns=document.querySelector('#netDns').value.trim();if(dns)payload.dns=dns}
  if(!payload.interface){toast('Pick an interface');return}
  if(!confirm('Apply new network settings to '+payload.interface+'?\n\nThe change goes live immediately. If you don\'t press "Keep this change" within '+payload.grace_seconds+'s, it auto-reverts.'))return;
  const st=document.querySelector('#netStatus');st.textContent='submitting…';st.classList.remove('bad');
  try{const d=await api('/api/network',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});st.textContent='queued — the reconciler will apply within a few seconds';netState=d;renderNetwork(d);setTimeout(loadNetwork,3000)}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function confirmNetwork(){try{const d=await api('/api/network/confirm',{method:'POST'});toast('Change kept');renderNetwork(d);setTimeout(loadNetwork,1500)}catch(e){toast(e.message)}}
function activateView(v){const btn=document.querySelector('nav button[data-view="'+v+'"]');const pane=document.querySelector('#'+v);if(!btn||!pane)return;document.querySelectorAll('nav button,.view').forEach(e=>e.classList.remove('active'));btn.classList.add('active');pane.classList.add('active');if(v==='wifi'){loadWifi();loadWifiMap();loadWifiEvents();loadSpectrum(false)}if(v==='heatmap')hmInit();if(v==='security'){loadIds();loadIdsAdapter()}if(v==='neighbours')loadLldp();if(v==='settings'){loadSettings();loadCustomServices();loadMonitorConfig();loadNetwork();loadAccount();loadAlerting();loadEvidence()}if(v==='apwatch')loadApWatch();if(v==='jobs')loadJobs();if(v==='overview')loadAttention();if(v==='actions'){loadCatalog();loadTrafficAllow()}if(v==='assets')loadAssets();if(v==='collectors')loadCollectors();if(v==='map')loadMap();if(v==='dangerous')loadDangerous()}
document.querySelectorAll('nav button[data-view]').forEach(b=>b.onclick=()=>activateView(b.dataset.view));
// --- Access-point watch (continuous RF) ---
async function loadApWatch(){const st=document.querySelector('#apStatus');st.textContent='loading…';st.classList.remove('bad');try{renderApWatch(await api('/api/wifi/ap-monitor'))}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function apScanNow(){const st=document.querySelector('#apStatus');st.textContent='scanning…';st.classList.remove('bad');try{const d=await api('/api/wifi/ap-monitor/scan',{method:'POST'});const parts=[];if((d.appeared||[]).length)parts.push(`${d.appeared.length} appeared`);if((d.disappeared||[]).length)parts.push(`${d.disappeared.length} disappeared`);toast(`Scan: ${d.scanned} AP(s)${parts.length?' · '+parts.join(', '):''}`);await loadApWatch()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderApWatch(d){const st=document.querySelector('#apStatus');const cfg=d.config||{};const aps=d.access_points||[];const present=aps.filter(a=>a.present),gone=aps.filter(a=>!a.present);const upd=d.last_update?new Date(d.last_update*1000).toLocaleString():'never';st.textContent=`${present.length} present · ${gone.length} gone · watch ${cfg.enabled===false?'disabled':'every '+(cfg.interval||60)+'s'} · last scan ${upd}`;st.classList.toggle('bad',cfg.enabled===false);if(!(d.wireless||[]).length){st.textContent+=' · no wireless interface (enable the radio, then Scan now)';st.classList.add('bad')}
  document.querySelector('#apSummary').innerHTML=[`<span class="chip ok">${present.length} on air</span>`,gone.length?`<span class="chip warn">${gone.length} gone</span>`:'',`<span class="chip">${(d.events||[]).length} logged events</span>`].filter(Boolean).join('');
  const apRow=a=>`<tr class="${a.present?'':'muted'}"><td>${a.present?'●':'○'} ${esc(a.ssid||'(hidden)')}</td><td>${esc(a.bssid)}</td><td>${esc(a.band||'')}${a.channel!=null?' ch'+a.channel:''}</td><td>${esc(a.signal||'—')}</td><td>${esc(a.security||'')}</td><td>${a.last_seen?new Date(a.last_seen*1000).toLocaleTimeString():'—'}</td></tr>`;
  document.querySelector('#apList').innerHTML=`<table><thead><tr><th>SSID</th><th>BSSID</th><th>Band/Ch</th><th>Signal</th><th>Security</th><th>Last seen</th></tr></thead><tbody>${aps.map(apRow).join('')||'<tr><td colspan="6">no APs recorded yet — enable the radio and Scan now</td></tr>'}</tbody></table>`;
  const evRow=e=>`<tr><td>${new Date(e.ts*1000).toLocaleString()}</td><td class="${e.event==='disappeared'?'bad':'ok'}">${esc(e.event)}</td><td>${esc(e.ssid||'(hidden)')}</td><td>${esc(e.detail||'')}</td></tr>`;
  document.querySelector('#apEvents').innerHTML=`<table><thead><tr><th>When</th><th>Event</th><th>SSID</th><th>Detail</th></tr></thead><tbody>${(d.events||[]).map(evRow).join('')||'<tr><td colspan="4">no appear/disappear events yet</td></tr>'}</tbody></table>`}
// --- Collectors: multi-node fleet, status, self-update ----------------------
// Effective UP/DOWN comes first from liveness (is it still pinging?), then the
// agent's self-reported lifecycle status colours the detail.
function collectorState(c){if(c.local)return{label:'LOCAL',cls:'ok'};if(!c.online)return{label:'DOWN',cls:'bad'};const s=(c.status||'RUNNING').toUpperCase();if(s==='DEGRADED')return{label:'DEGRADED',cls:'warn'};if(s==='STARTING')return{label:'STARTING',cls:'warn'};return{label:'UP',cls:'ok'}}
async function loadCollectors(){const st=document.querySelector('#collectorsStatus');st.textContent='loading…';st.classList.remove('bad');try{const d=await api('/api/collectors');collectorsCfg=d;document.querySelector('#mnRole').value=(d.local&&d.local.role)||'standalone';document.querySelector('#mnAccept').checked=!!d.accept_external_collectors;document.querySelector('#collectorsRelease').innerHTML=d.latest_version?`<span class="chip ok">release available · v${esc(d.latest_version)}</span>`:'<span class="chip warn">no collector release built — run scripts/build-collector.sh</span>';renderCollectors(d);st.textContent=`${(d.collectors||[]).length} enrolled · ${(d.collectors||[]).filter(c=>c.online).length} up`}catch(e){st.textContent=e.message;st.classList.add('bad')}}
let collectorsCfg={};
function renderCollectors(d){const rows=(d.collectors||[]).map(c=>{const s=collectorState(c);const ver=c.version?esc(c.version):'—';const behind=c.update_available;const verCell=behind?`${ver} <span class="chip warn">→ v${esc(c.latest_version)}</span>`:ver;const det=(c.status_meta&&c.status_meta.last_error)?`<div class="hint bad">${esc(c.status_meta.last_error)}</div>`:'';const host=c.hostname?esc(c.hostname):'—';const acts=[];if(!c.enabled)acts.push('<span class="chip bad">revoked</span>');if(c.update_requested)acts.push('<span class="chip warn">update pending…</span>');else if(behind)acts.push(`<button onclick="updateCollector('${esc(c.collector_id)}')" title="Push the latest agent to this collector">Update</button>`);acts.push(`<button onclick="rotateKey('${esc(c.collector_id)}')" title="Issue a fresh key, invalidating the old one">Rotate key</button>`);acts.push(c.enabled?`<button onclick="revokeCollector('${esc(c.collector_id)}')" title="Invalidate this collector's key">Revoke</button>`:`<button onclick="rotateKey('${esc(c.collector_id)}')">Re-enable (new key)</button>`);acts.push(`<button onclick="deleteCollector('${esc(c.collector_id)}')" title="Remove this collector and its data">Delete</button>`);return `<tr><td>${esc(c.name||c.collector_id)}<div class="hint">${esc(c.collector_id)}</div></td><td>${host}${c.node_ip?`<div class="hint">${ipLink(c.node_ip)}</div>`:''}</td><td>${verCell}</td><td><span class="chip ${s.cls}">${s.label}</span>${det}</td><td>${c.last_seen?fmtAge((Date.now()/1000)-c.last_seen):'never'}</td><td class="hint">${esc(c.key_prefix||'')}…</td><td>${acts.join(' ')}</td></tr>`}).join('');document.querySelector('#collectorsList').innerHTML=`<table><thead><tr><th>Name</th><th>Host / IP</th><th>Agent version</th><th>Status</th><th>Last ping</th><th>Key</th><th>Actions</th></tr></thead><tbody>${rows||'<tr><td colspan="7">No collectors enrolled yet. Click “Enroll collector”, then install the agent on the remote node with the key.</td></tr>'}</tbody></table>`}
async function saveMultinode(){const role=document.querySelector('#mnRole').value;const accept_external_collectors=document.querySelector('#mnAccept').checked;const st=document.querySelector('#mnStatus');st.textContent='saving…';st.classList.remove('bad');try{await api('/api/multinode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role,accept_external_collectors})});st.textContent='saved';setTimeout(()=>st.textContent='',1500)}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function enrollCollector(){const name=window.prompt('Name this collector (e.g. "branch-office-gw"):','');if(name===null)return;try{const r=await api('/api/collectors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim()})});showCollectorKey(r);loadCollectors()}catch(e){toast(e.message)}}
// The plaintext key is shown ONCE (never stored in the clear) — surface it in the
// modal with the exact install command so it can be copied before it is gone.
function showCollectorKey(r){const agg=`${location.protocol}//${location.hostname}:${location.port||'8088'}`;const sec=r.update_secret?` \\\n     UPDATE_SECRET=${r.update_secret}`:'';const cmd=`sudo AGGREGATOR_URL=${agg} \\\n     INGEST_KEY=${r.key}${sec} \\\n     COLLECTOR_ID=${r.collector_id} \\\n     ./scripts/install-collector.sh --apply`;document.querySelector('#alertDetailTitle').textContent='Collector enrolled · '+r.collector_id;document.querySelector('#alertDetailBody').innerHTML=`<p class="hint bad">This key and signing secret are shown once and cannot be retrieved again. Copy them now.</p><div class="chips"><span class="chip">${esc(r.name||r.collector_id)}</span><span class="chip">${esc(r.collector_id)}</span></div><p class="eyebrow" style="margin-top:.6rem">INGEST KEY</p><pre>${esc(r.key)}</pre>${r.update_secret?`<p class="eyebrow">UPDATE SIGNING SECRET <span class="hint">(authorizes remote agent updates)</span></p><pre>${esc(r.update_secret)}</pre>`:''}<p class="eyebrow">INSTALL ON THE COLLECTOR NODE</p><pre>${esc(cmd)}</pre><p class="hint">Make sure “accept data from external collectors” is enabled above, or ingest will be refused.</p>`;document.querySelector('#alertDetail').style.display='flex'}
async function updateCollector(id){if(!confirm('Push the latest agent to this collector? It self-updates and restarts on its next ping.'))return;try{const r=await api('/api/collectors/'+encodeURIComponent(id)+'/update',{method:'POST'});toast('Update requested → v'+r.target_version);loadCollectors()}catch(e){toast(e.message)}}
async function rotateKey(id){if(!confirm('Issue a fresh key for this collector? The current key stops working immediately and the collector must be reconfigured with the new key.'))return;try{const r=await api('/api/collectors/'+encodeURIComponent(id)+'/rotate',{method:'POST'});showCollectorKey({collector_id:id,key:r.key,update_secret:r.update_secret,name:id});loadCollectors()}catch(e){toast(e.message)}}
async function revokeCollector(id){if(!confirm('Revoke this collector’s key? It can no longer push data until you issue a new key.'))return;try{await api('/api/collectors/'+encodeURIComponent(id)+'/revoke',{method:'POST'});toast('Revoked');loadCollectors()}catch(e){toast(e.message)}}
async function deleteCollector(id){if(!confirm('Delete this collector and all its pushed data? This cannot be undone.'))return;try{await api('/api/collectors/'+encodeURIComponent(id),{method:'DELETE'});toast('Deleted');loadCollectors()}catch(e){toast(e.message)}}
// --- Dangerous actions (roadmap P5): excluded-by-default capability register ---
// Read-only view of what the probe deliberately does NOT do. The master switch
// and per-item acknowledgement are governance/audit gates only: even fully
// unlocked, /api/dangerous/<id>/run refuses because nothing here is implemented.
let daState={enabled:false,actions:[]};
async function loadDangerous(){const st=document.querySelector('#daMasterStatus');st.textContent='loading…';st.classList.remove('bad');try{daState=await api('/api/dangerous');document.querySelector('#daMaster').checked=!!daState.enabled;st.textContent=daState.enabled?'ENABLED — items are unlocked but still refuse to execute':'disabled (safe default)';st.classList.toggle('bad',!!daState.enabled);renderDangerous()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
function renderDangerous(){const acts=daState.actions||[];const master=!!daState.enabled;const row=a=>{const ackId='daAck-'+a.id;const badge=a.implemented?'<span class="chip warn">implemented</span>':'<span class="chip ok">not implemented</span>';const runBtn=`<button ${(!master||!a.acknowledged)?'disabled':''} onclick="daRun('${esc(a.id)}')" title="Attempt this action (this build refuses by design)">Attempt</button>`;return `<tr><td><strong>${esc(a.title)}</strong><div class="hint">${esc(a.category)} · ${esc(a.id)}</div></td><td class="hint">${esc(a.risk)}</td><td>${badge}</td><td><label class="inline"><input type="checkbox" ${a.acknowledged?'checked':''} ${master?'':'disabled'} onchange="daAck('${esc(a.id)}',this.checked)"> acknowledged</label></td><td>${runBtn}</td></tr>`};document.querySelector('#daList').innerHTML=`<table><thead><tr><th>Excluded capability</th><th>Why it is dangerous</th><th>Build status</th><th>Acknowledge</th><th></th></tr></thead><tbody>${acts.map(row).join('')}</tbody></table>`}
async function daPutDanger(patch){return api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({dangerous_actions:patch})})}
async function daToggleMaster(){const on=document.querySelector('#daMaster').checked;if(on&&!confirm('Enable dangerous actions?\n\nThis unlocks the excluded-by-default register. Only do this under explicit written authorization for a specific engagement. Even enabled, this build will NOT execute the destructive techniques — every attempt is refused and audited.'))
  {document.querySelector('#daMaster').checked=false;return}
  try{await daPutDanger({enabled:on});toast(on?'Dangerous actions ENABLED (audited)':'Dangerous actions disabled');await loadDangerous()}catch(e){toast(e.message);await loadDangerous()}}
async function daAck(id,on){const ack={};(daState.actions||[]).forEach(a=>{if(a.acknowledged)ack[a.id]=true});ack[id]=on;try{await daPutDanger({acknowledged:ack});await loadDangerous()}catch(e){toast(e.message);await loadDangerous()}}
async function daRun(id){try{const r=await api('/api/dangerous/'+encodeURIComponent(id)+'/run',{method:'POST'});toast((r.executed?'Executed: ':'Refused: ')+r.reason)}catch(e){let m=e.message;toast('Refused: '+m)}}
// --- Settings: outage-monitor config editor ---
let mcMeta={groups:[],service_kinds:[]};
const MC_SPEC={
  targets:{sel:'#mcTargets',cols:[{f:'enabled',type:'check'},{f:'started',type:'toggle'},{f:'name',ph:'name'},{f:'address',ph:'IP/host'},{f:'interface',type:'adapter'},{f:'group',type:'group'}]},
  services:{sel:'#mcServices',cols:[{f:'enabled',type:'check'},{f:'started',type:'toggle'},{f:'name',ph:'name'},{f:'kind',type:'kind'},{f:'target',ph:'host / host:port / url'}]},
  ports:{sel:'#mcPorts',cols:[{f:'enabled',type:'check'},{f:'started',type:'toggle'},{f:'name',ph:'name'},{f:'host',ph:'host'},{f:'port',ph:'port',num:true},{f:'proto',type:'proto'},{f:'send',ph:'send (optional)'},{f:'expect',ph:'expect (optional)'}]},
};
function mcCell(col,val){val=val==null?'':val;const attr=`data-mc-field="${col.f}"`;if(col.type==='check'){const on=val!==false;return `<input type="checkbox" ${attr} ${on?'checked':''} onchange="mcEnableChanged(this)" title="Enabled: include this probe in monitoring and in Start all">`}if(col.type==='toggle'){const on=val!==false;return `<button type="button" class="mc-run" ${attr} data-on="${on?'1':''}" onclick="mcToggleRun(this)" title="Start/stop this probe">${on?'▶ started':'⏸ stopped'}</button>`}if(col.type==='adapter'){const list=mcMeta.adapters||[];const seen=new Set();let opts=`<option value=""${String(val)===''?' selected':''}>— auto (OS routes) —</option>`;for(const a of list){seen.add(a.name);opts+=`<option value="${esc(a.name)}"${String(a.name)===String(val)?' selected':''}>${esc(a.name)}${a.state?' ('+esc(a.state)+')':''}</option>`}if(val&&!seen.has(String(val)))opts+=`<option value="${esc(val)}" selected>${esc(val)} (not present)</option>`;return `<select ${attr}>${opts}</select>`}if(col.type){const opts=col.type==='group'?mcMeta.groups:col.type==='kind'?mcMeta.service_kinds:['tcp','udp'];return `<select ${attr}>${opts.map(o=>`<option ${String(o)===String(val)?'selected':''}>${esc(o)}</option>`).join('')}</select>`}return `<input ${attr} type="${col.num?'number':'text'}" value="${esc(val)}" placeholder="${esc(col.ph||'')}">`}
function mcRowHtml(kind,row){const spec=MC_SPEC[kind];return `<tr data-mc-row>${spec.cols.map(c=>`<td>${mcCell(c,row[c.f])}</td>`).join('')}<td><button onclick="this.closest('tr').remove()" title="remove row">✕</button></td></tr>`}
function mcRender(kind,rows){const spec=MC_SPEC[kind];const head=spec.cols.map(c=>`<th>${esc(c.f)}</th>`).join('')+'<th></th>';document.querySelector(spec.sel).innerHTML=`<table><thead><tr>${head}</tr></thead><tbody>${(rows||[]).map(r=>mcRowHtml(kind,r)).join('')}</tbody></table>`}
function mcAddRow(kind){const spec=MC_SPEC[kind];const row={enabled:true,started:false};const tbody=document.querySelector(spec.sel+' tbody');if(!tbody){mcRender(kind,[row]);return}tbody.insertAdjacentHTML('beforeend',mcRowHtml(kind,row))}
function mcSetRun(btn,on){btn.dataset.on=on?'1':'';btn.textContent=on?'▶ started':'⏸ stopped';btn.closest('tr').classList.toggle('mc-off',!on)}
function mcSyncRun(){const sel=['#mcTargets','#mcServices','#mcPorts'].map(s=>s+' tr[data-mc-row]').join(',');document.querySelectorAll(sel).forEach(tr=>{const en=tr.querySelector('[data-mc-field="enabled"]'),btn=tr.querySelector('.mc-run');if(btn){if(en)btn.disabled=!en.checked;tr.classList.toggle('mc-off',btn.dataset.on!=='1')}if(en)tr.classList.toggle('mc-disabled',!en.checked)})}
function mcToggleRun(btn){mcSetRun(btn,btn.dataset.on!=='1');saveMonitorConfig()}
function mcEnableChanged(cb){const tr=cb.closest('tr'),btn=tr.querySelector('.mc-run');if(btn)btn.disabled=!cb.checked;tr.classList.toggle('mc-disabled',!cb.checked);saveMonitorConfig()}
// Start all: only rows whose Enabled box is ticked (disabled probes stay stopped).
// Stop all: every probe off, regardless of Enabled.
function mcToggleAll(run){const sel=['#mcTargets','#mcServices','#mcPorts'].map(s=>s+' tr[data-mc-row]').join(',');document.querySelectorAll(sel).forEach(tr=>{const en=tr.querySelector('[data-mc-field="enabled"]'),btn=tr.querySelector('.mc-run');if(!btn)return;if(run){if(en&&!en.checked)return;mcSetRun(btn,true)}else{mcSetRun(btn,false)}});saveMonitorConfig()}
function mcCollect(kind){const spec=MC_SPEC[kind];return [...document.querySelectorAll(spec.sel+' tr[data-mc-row]')].map(tr=>{const o={};spec.cols.forEach(c=>{const el=tr.querySelector(`[data-mc-field="${c.f}"]`);if(c.type==='check'){o[c.f]=el?el.checked:true;return}if(c.type==='toggle'){o[c.f]=el?el.dataset.on==='1':false;return}let v=el?el.value.trim():'';if(c.num)v=v?+v:'';o[c.f]=v});return o}).filter(o=>spec.cols.some(c=>!c.type&&String(o[c.f]).trim()!==''))}
async function loadMonitorConfig(){try{const d=await api('/api/monitor/config');mcMeta={groups:d.groups||[],service_kinds:d.service_kinds||[],adapters:d.adapters||[]};document.querySelector('#mcSource').textContent=d.source==='csv'?'Showing the monitor’s current /etc CSV config — saving switches it to this editable config.':'';mcRender('targets',d.targets||[]);mcRender('services',d.services||[]);mcRender('ports',d.ports||[]);mcSyncRun();const ap=d.ap_monitor||{};document.querySelector('#mcApEnabled').checked=ap.enabled!==false;document.querySelector('#mcApInterval').value=ap.interval||60;document.querySelector('#mcErrors').textContent=''}catch(e){toast(e.message)}}
async function saveMonitorConfig(){const body={targets:mcCollect('targets'),services:mcCollect('services'),ports:mcCollect('ports'),ap_monitor:{enabled:document.querySelector('#mcApEnabled').checked,interval:+document.querySelector('#mcApInterval').value||60}};const st=document.querySelector('#mcSaveStatus'),err=document.querySelector('#mcErrors');st.textContent='saving…';st.classList.remove('bad');err.innerHTML='';try{const r=await fetch('/api/monitor/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){st.textContent='not saved';st.classList.add('bad');err.innerHTML=(d.details||[d.error||r.statusText]).map(x=>`<div class="bad">• ${esc(x)}</div>`).join('');return}st.textContent='saved — the monitor reloads within seconds';document.querySelector('#mcSource').textContent='';mcRender('targets',d.targets||[]);mcRender('services',d.services||[]);mcRender('ports',d.ports||[]);mcSyncRun()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
// --- Network map (#38 SPA view, #40 modes/search/filter/export) -------------
const MAP_ICON={internet:'🌐','wan-gateway':'🛰️',firewall:'🧱',router:'📶',switch:'🔀',ap:'📡',subnet:'🗂️',self:'🛡️',collector:'📥',server:'🖥️',workstation:'💻',printer:'🖨️',phone:'☎️',camera:'📷',iot:'🔌',host:'📦',neighbour:'🔗',target:'🎯',hop:'·',unknown:'❔'};
const MAP_STATUS={up:'#3fb950',warning:'#d29922',down:'#f85149',unreachable:'#f85149',unknown:'#7d8ea0'};
const MAP_TIER={internet:0,'wan-gateway':1,firewall:1,collector:2,router:2,switch:3,ap:3,subnet:4};
const mapTier=k=>MAP_TIER[k]!==undefined?MAP_TIER[k]:5;
let mapState={data:null,tags:{},mode:'hybrid',q:'',kind:'',status:'',collector:'all',view:null,wired:false,sel:null};
async function loadMap(){const empty=document.querySelector('#mapEmpty');try{const qs=mapState.collector&&mapState.collector!=='all'?'?collector='+encodeURIComponent(mapState.collector):'';const[g,t]=await Promise.all([api('/api/map'+qs),api('/api/map/tags')]);mapState.data=g;mapState.tags=t.tags||{};mapPopulateCollectors(g.collectors||[]);mapPopulateKinds(t.kinds||[],g.nodes);mapLayout(g.nodes);if(!mapState.view)mapFit(true);mapRender();mapWirePanZoom()}catch(e){if(empty){empty.style.display='block';empty.textContent=e.message}}}
function mapPopulateCollectors(list){const sel=document.querySelector('#mapCollector');if(!sel)return;const uniq=['all',...list.filter(c=>c&&c!=='all')];sel.innerHTML=uniq.map(c=>`<option value="${esc(c)}">${c==='all'?'all collectors':esc(c)}</option>`).join('');sel.value=uniq.includes(mapState.collector)?mapState.collector:'all';if(sel.value!==mapState.collector)mapState.collector=sel.value}
function mapSetCollector(v){mapState.collector=v||'all';mapState.view=null;loadMap()}
function mapPopulateKinds(tagKinds,nodes){const present=[...new Set(nodes.map(n=>n.kind))].sort();const kf=document.querySelector('#mapKind');const cur=kf.value;kf.innerHTML='<option value="">all kinds</option>'+present.map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('');kf.value=cur;const tk=document.querySelector('#mapTagKind');if(tk)tk.innerHTML=(tagKinds.length?tagKinds:present).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}
function mapLayout(nodes){const byTier={};nodes.forEach(n=>{const t=mapTier(n.kind);(byTier[t]=byTier[t]||[]).push(n)});const tiers=Object.keys(byTier).map(Number).sort((a,b)=>a-b);const colW=180,rowH=140,padX=110,padY=80;let maxCols=1;tiers.forEach(t=>maxCols=Math.max(maxCols,byTier[t].length));const width=padX*2+(maxCols-1)*colW;tiers.forEach((t,ti)=>{const row=byTier[t].sort((a,b)=>String(a.subnet||'').localeCompare(String(b.subnet||''))||String(a.label).localeCompare(String(b.label)));const span=(row.length-1)*colW;const startX=(width-span)/2;row.forEach((node,i)=>{node._x=startX+i*colW;node._y=padY+ti*rowH})});mapState.content={w:Math.max(width,640),h:Math.max(padY*2+(tiers.length-1)*rowH,320)}}
function mapEdgeStyle(e){if(e.media==='wireless')return{c:'#60a5fa',w:1.6,d:'2 5'};if(e.confidence!=='observed')return{c:'#4a5a6a',w:1.4,d:'5 4'};if(e.layer==='l1')return{c:'#5eead4',w:1.8,d:''};return{c:'#3a4b5c',w:1.6,d:''}}
function mapEdgeVisible(e){const m=mapState.mode;if(m==='hybrid')return true;if(m==='l1')return e.layer==='l1';if(m==='l2')return e.layer==='l2'||e.layer==='l1';if(m==='l3')return e.layer==='l3'||e.layer==='vpn';return true}
function mapMatches(n){if(mapState.kind&&n.kind!==mapState.kind)return false;if(mapState.status&&n.status!==mapState.status)return false;const q=mapState.q.trim().toLowerCase();if(q){const hay=[n.label,n.kind,n.status,n.vendor,n.subnet,...(n.ips||[]),...(n.macs||[])].join(' ').toLowerCase();if(!hay.includes(q))return false}return true}
function mapRender(){const d=mapState.data;if(!d)return;const empty=document.querySelector('#mapEmpty');if(empty)empty.style.display=d.nodes.length?'none':'block';const byId={};d.nodes.forEach(n=>byId[n.id]=n);const active=mapState.q||mapState.kind||mapState.status;const isMatch={};d.nodes.forEach(n=>isMatch[n.id]=mapMatches(n));let matchCount=0;d.nodes.forEach(n=>{if(isMatch[n.id])matchCount++});
  const visEdges=d.edges.filter(e=>mapEdgeVisible(e)&&byId[e.from]&&byId[e.to]);const edges=visEdges.map(e=>{const a=byId[e.from],b=byId[e.to],s=mapEdgeStyle(e);const dim=active&&!(isMatch[e.from]&&isMatch[e.to]);const my=(a._y+b._y)/2;return `<path class="map-edge${dim?' dim':''}" d="M${a._x} ${a._y} C${a._x} ${my} ${b._x} ${my} ${b._x} ${b._y}" stroke="${s.c}" stroke-width="${s.w}"${s.d?` stroke-dasharray="${s.d}"`:''}/>`}).join('');
  const nodes=d.nodes.map(n=>{const col=MAP_STATUS[n.status]||MAP_STATUS.unknown;const tagged=!!mapState.tags[n.id];const dim=active&&!isMatch[n.id];const mtc=active&&isMatch[n.id];const cls=`map-node${dim?' dim':''}${mtc?' match':''}${tagged?' tagged':''}`;const label=String(n.label||n.id);const short=label.length>18?label.slice(0,17)+'…':label;const sub=(n.ips&&n.ips[0])&&n.ips[0]!==label?n.ips[0]:(n.kind!=='subnet'?n.kind:'');const shape=n.kind==='subnet'?`<rect x="-34" y="-20" width="68" height="40" rx="8" fill="#0d1a20" stroke="${col}" stroke-width="2"/>`:`<circle r="22" fill="#0d1a20" stroke="${col}" stroke-width="2.5"/>`;return `<g class="${cls}" data-node="${esc(n.id)}" transform="translate(${n._x} ${n._y})">${shape}<text class="nicon" text-anchor="middle" dy="6" font-size="18" pointer-events="none">${MAP_ICON[n.kind]||MAP_ICON.unknown}</text><text class="nlabel" text-anchor="middle" y="40" fill="${col==='#7d8ea0'?'#c6d2de':'#e8eef4'}">${esc(short)}</text>${sub?`<text class="nsub" text-anchor="middle" y="53">${esc(String(sub).slice(0,22))}</text>`:''}</g>`}).join('');
  const c=mapState.content,v=mapState.view;const canvas=document.querySelector('#mapCanvas');const tip=document.querySelector('#mapTip');canvas.querySelectorAll('svg').forEach(s=>s.remove());canvas.insertAdjacentHTML('beforeend',`<svg viewBox="${v.x} ${v.y} ${v.w} ${v.h}" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg"><g>${edges}${nodes}</g></svg>`);
  canvas.querySelectorAll('.map-node').forEach(g=>{const id=g.getAttribute('data-node');g.addEventListener('click',ev=>{ev.stopPropagation();mapPick(id)});g.addEventListener('mouseenter',()=>mapShowTip(id));g.addEventListener('mousemove',ev=>mapMoveTip(ev));g.addEventListener('mouseleave',()=>{if(tip)tip.style.display='none'})});
  mapLegend();document.querySelector('#mapStat').textContent=`${d.nodes.length} node(s) · ${visEdges.length} link(s) shown${active?` · ${matchCount} match`:''} · updated ${d.updated?new Date(d.updated*1000).toLocaleTimeString():'—'}`}
function mapLegend(){document.querySelector('#mapLegend').innerHTML=[['legdot','#3fb950','up'],['legdot','#f85149','down'],['legdot','#7d8ea0','unknown']].map(([c,col,t])=>`<span class="chip"><span class="${c}" style="background:${col}"></span>${t}</span>`).join('')+['#5eead4 solid wired','#60a5fa dotted Wi-Fi','#4a5a6a dashed inferred'].map(x=>{const[col,style,t]=x.split(' ');return `<span class="chip"><span class="legline" style="border-top-color:${col};border-top-style:${style==='dotted'?'dotted':style==='dashed'?'dashed':'solid'}"></span>${t}</span>`}).join('')}
function mapShowTip(id){const n=(mapState.data.nodes||[]).find(x=>x.id===id);if(!n)return;const tip=document.querySelector('#mapTip');const dt=n.detail||{};const bits=[`<b>${esc(n.label||n.id)}</b>`,`kind: ${esc(n.kind)}${mapState.tags[id]?' (tagged)':''}`,`status: ${esc(n.status)}`];if(n.vendor)bits.push('vendor: '+esc(n.vendor));if(n.ips&&n.ips.length)bits.push('ip: '+esc(n.ips.join(', ')));if(n.macs&&n.macs.length)bits.push('mac: '+esc(n.macs.join(', ')));if(dt.rtt_ms!=null)bits.push('rtt: '+dt.rtt_ms+' ms');if(dt.loss_pct!=null)bits.push('loss: '+dt.loss_pct+'%');if(dt.class_reason)bits.push('why: '+esc(dt.class_reason));tip.innerHTML=bits.join('<br>');tip.style.display='block'}
function mapMoveTip(ev){const tip=document.querySelector('#mapTip'),r=document.querySelector('#mapCanvas').getBoundingClientRect();let x=ev.clientX-r.left+14,y=ev.clientY-r.top+14;if(x+300>r.width)x=r.width-300;tip.style.left=x+'px';tip.style.top=y+'px'}
function mapPick(id){const n=(mapState.data.nodes||[]).find(x=>x.id===id);if(!n)return;mapState.sel=id;const drawer=document.querySelector('#mapDrawer');document.querySelector('#mapDrawerTitle').textContent=n.label||n.id;const dt=n.detail||{};const rows=[['Kind',esc(n.kind)+(mapState.tags[id]?' <span class="chip">tagged</span>':'')],['Status',`<span style="color:${MAP_STATUS[n.status]||MAP_STATUS.unknown}">${esc(n.status)}</span>`],['IPs',(n.ips||[]).map(ipLink).join(' ')||'—'],['MACs',esc((n.macs||[]).join(', ')||'—')],['Vendor',esc(n.vendor||'—')],['Subnet',esc(n.subnet||'—')],['Confidence',esc(n.confidence||'—')],['Observed by',esc(n.collector||'local')]];if(dt.rtt_ms!=null)rows.push(['RTT',dt.rtt_ms+' ms']);if(dt.loss_pct!=null)rows.push(['Loss (24h)',dt.loss_pct+'%']);if(dt.class_reason)rows.push(['Classified by',esc(dt.class_source||'')+' — '+esc(dt.class_reason)]);if(dt.notes)rows.push(['Notes',esc(dt.notes)]);if(dt.tags)rows.push(['Tags',dt.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join(' ')]);const dossier=(n.ips&&n.ips.length)?`<div class="form-row"><button onclick="showIp('${esc(n.ips[0])}')">Open full IP dossier ↗</button></div>`:'';document.querySelector('#mapDrawerBody').innerHTML=`<div class="table-wrap"><table><tbody>${rows.map(([k,v])=>`<tr><th style="width:9rem">${k}</th><td style="white-space:normal">${v}</td></tr>`).join('')}</tbody></table></div>${dossier}`;const tag=mapState.tags[id]||{};document.querySelector('#mapTagKind').value=tag.kind||n.kind;document.querySelector('#mapTagLabel').value=tag.label||'';document.querySelector('#mapTagTags').value=(tag.tags||[]).join(', ');document.querySelector('#mapTagNotes').value=tag.notes||'';document.querySelector('#mapTagStatus').textContent='';drawer.style.display='block';drawer.scrollIntoView({behavior:'smooth',block:'nearest'})}
function mapCloseDrawer(){document.querySelector('#mapDrawer').style.display='none';mapState.sel=null}
async function mapSaveTag(){const id=mapState.sel;if(!id)return;const st=document.querySelector('#mapTagStatus');st.textContent='saving…';st.classList.remove('bad');const body={kind:document.querySelector('#mapTagKind').value,label:document.querySelector('#mapTagLabel').value,notes:document.querySelector('#mapTagNotes').value,tags:document.querySelector('#mapTagTags').value};try{await api('/api/map/tags/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Tag saved');await loadMap();mapPick(id)}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function mapClearTag(){const id=mapState.sel;if(!id)return;try{await api('/api/map/tags/'+encodeURIComponent(id),{method:'DELETE'});toast('Tag cleared');await loadMap();mapPick(id)}catch(e){document.querySelector('#mapTagStatus').textContent=e.message}}
function mapSetMode(m){mapState.mode=m;document.querySelectorAll('#mapModes button').forEach(b=>b.classList.toggle('primary',b.dataset.mode===m));mapRender()}
function mapSearch(v){mapState.q=v;mapRender()}
function mapSetFilter(){mapState.kind=document.querySelector('#mapKind').value;mapState.status=document.querySelector('#mapStatus').value;mapRender()}
function mapFit(noRender){const c=mapState.content||{w:640,h:320};const pad=40;mapState.view={x:-pad,y:-pad,w:c.w+pad*2,h:c.h+pad*2};if(!noRender)mapRender()}
function mapWirePanZoom(){if(mapState.wired)return;const canvas=document.querySelector('#mapCanvas');mapState.wired=true;canvas.addEventListener('wheel',ev=>{ev.preventDefault();const v=mapState.view;if(!v)return;const r=canvas.getBoundingClientRect();const fx=(ev.clientX-r.left)/r.width,fy=(ev.clientY-r.top)/r.height;const k=ev.deltaY<0?0.88:1.14;const nw=Math.min(Math.max(v.w*k,200),12000),nh=nw*(v.h/v.w);v.x+=(v.w-nw)*fx;v.y+=(v.h-nh)*fy;v.w=nw;v.h=nh;mapRender()},{passive:false});let drag=null;canvas.addEventListener('pointerdown',ev=>{drag={x:ev.clientX,y:ev.clientY,vx:mapState.view.x,vy:mapState.view.y};canvas.classList.add('grabbing');canvas.setPointerCapture(ev.pointerId)});canvas.addEventListener('pointermove',ev=>{if(!drag)return;const r=canvas.getBoundingClientRect();const v=mapState.view;v.x=drag.vx-(ev.clientX-drag.x)/r.width*v.w;v.y=drag.vy-(ev.clientY-drag.y)/r.height*v.h;mapRender()});const end=()=>{drag=null;canvas.classList.remove('grabbing')};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointerleave',end);canvas.addEventListener('click',ev=>{if(ev.target.closest('.map-node'))return})}
function mapExport(kind){const svg=document.querySelector('#mapCanvas svg');if(!svg){toast('nothing to export');return}const clone=svg.cloneNode(true);const c=mapState.content||{w:640,h:320};clone.setAttribute('viewBox',`-40 -40 ${c.w+80} ${c.h+80}`);clone.setAttribute('width',c.w+80);clone.setAttribute('height',c.h+80);clone.querySelectorAll('.dim').forEach(e=>e.removeAttribute('class'));clone.insertAdjacentHTML('afterbegin',`<rect x="-40" y="-40" width="${c.w+80}" height="${c.h+80}" fill="#091017"/>`);const xml='<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(clone);if(kind==='svg'){mapDownload(new Blob([xml],{type:'image/svg+xml'}),'network-map.svg');return}const img=new Image();img.onload=()=>{const cv=document.createElement('canvas');cv.width=(c.w+80)*2;cv.height=(c.h+80)*2;const ctx=cv.getContext('2d');ctx.scale(2,2);ctx.drawImage(img,0,0);cv.toBlob(b=>mapDownload(b,'network-map.png'))};img.src='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(xml)))}
function mapDownload(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
// --- auth gate: check session before booting the SPA ------------------------
function showLogin(show){const o=document.querySelector('#loginOverlay');o.style.display=show?'flex':'none';if(show)setTimeout(()=>{const p=document.querySelector('#loginPass');if(p)p.focus()},50)}
async function doLogin(ev){if(ev)ev.preventDefault();const st=document.querySelector('#loginStatus');st.textContent='signing in…';st.classList.remove('bad');
  try{const d=await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.querySelector('#loginUser').value,password:document.querySelector('#loginPass').value})});st.textContent='';showLogin(false);if(d.must_change)toast('You are on the default password — set a new one in Settings.');boot()}catch(e){st.textContent=e.message||'sign-in failed';st.classList.add('bad')}
  return false}
async function logout(){try{await fetch('/api/logout',{method:'POST'})}catch(e){}location.reload()}
async function changePassword(){const st=document.querySelector('#acctStatus');const u=document.querySelector('#acctUser').value.trim(),cur=document.querySelector('#acctCur').value,n=document.querySelector('#acctNew').value,n2=document.querySelector('#acctNew2').value;
  if(n!==n2){st.textContent='new passwords do not match';st.classList.add('bad');return}
  st.textContent='saving…';st.classList.remove('bad');
  try{const d=await api('/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,current_password:cur,new_password:n})});st.textContent='updated';document.querySelector('#acctCur').value='';document.querySelector('#acctNew').value='';document.querySelector('#acctNew2').value='';toast('Credentials updated');loadAccount()}catch(e){st.textContent=e.message;st.classList.add('bad')}}
async function loadAccount(){try{const s=await api('/api/auth/status');const who=document.querySelector('#acctWho');if(!s.auth_enabled){who.textContent='Auth is disabled on this instance.';return}if(s.username){document.querySelector('#acctUser').value=s.username;who.innerHTML=`Signed in as <strong>${esc(s.username)}</strong>.`+(s.must_change?' <span class="bad">Using the default password — please change it.</span>':'')}}catch(e){}}
function boot(){const qp=new URLSearchParams(location.search);const qv=qp.get('view');if(qv&&document.querySelector('nav button[data-view="'+qv+'"]'))activateView(qv);const qip=qp.get('ip');if(qip)showIp(qip).catch(()=>{});refresh().catch(e=>toast(e.message));loadAttention().catch(()=>{});setInterval(()=>refresh().catch(()=>{}),10000);setInterval(()=>{if(document.querySelector('#overview').classList.contains('active'))loadAttention().catch(()=>{})},30000);setInterval(()=>{if(document.querySelector('#apwatch').classList.contains('active'))loadApWatch().catch(()=>{})},20000);setInterval(()=>{if(document.querySelector('#map').classList.contains('active')&&!mapState.sel)loadMap().catch(()=>{})},30000)}
async function ensureAuthThenBoot(){let s;try{s=await api('/api/auth/status')}catch(e){s={auth_enabled:false,authenticated:true}}if(s.auth_enabled&&!s.authenticated){showLogin(true);return}boot()}
setInterval(()=>document.querySelector('#clock').textContent=new Date().toLocaleString(),1000);ensureAuthThenBoot();
